(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-video-diffusion-models-2022"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-1\">一 · 现场：一条 8 秒 720p 请求在午夜排队</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-2\">二 · 旧方案的第一层：整段视频一次性进注意力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-3\">三 · 旧方案的第二层：分块但无重叠，拼接处露馅</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-4\">四 · 旧方案的第三层：精度与 KV cache 的粗放管理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-5\">五 · 为什么非改不可：三个不可回避的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-6\">六 · 在线短视频生成的显存墙：从整段一次性推理到分块重叠的代价迁移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-7\">七 · 负载的四个可测维度：把“请求”拆成可记账的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-8\">八 · 并发与批大小：KV cache 是真正的约束面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-9\">九 · 长尾：p99 请求决定容量，而不是均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-10\">十 · SLO 口径：三种时延不可混用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-11\">十一 · 方案反过来限制负载：准入控制与降级策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-12\">十二 · 测量口径清单：可复核的最小集合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-13\">十三 · 负载画像如何反向锁死视频扩散的部署边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-14\">十四 · 时空注意力的 kernel 形状与精度落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-15\">十五 · 数据类型的分层：FP16/BF16、FP8、NVFP4</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-16\">十六 · 累加精度与误差传播路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-17\">十七 · Blackwell 的 tcgen05、TMEM 与 2-SM MMA</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-18\">十八 · 精度切换的工程判据与监控落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-19\">十九 · 精度下探的边界：从 BF16 到 NVFP4 在时空注意力与 VAE 解码上的失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-20\">二十 · 显存账本的三层结构：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-21\">二十一 · 分页与压缩：把 KV 从连续块变成可管理页</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-22\">二十二 · 复用与卸载：跨去噪步与跨块的两种时间尺度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-23\">二十三 · 带宽瓶颈定位：HBM3e 容量与有效带宽的换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-24\">二十四 · 一个可复算的显存预算：从参数到容量判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-25\">二十五 · 失败模式与监控落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-26\">二十六 · 从“整段生成”到“可调度单元”：扩散去噪步的批处理边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-27\">二十七 · Chunked prefill 的扩散变体：把分块与重叠纳入预填调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-28\">二十八 · 优先级与抢占：尾延迟从哪里来，怎么压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-29\">二十九 · 分离式预填/解码：把 VAE 解码从去噪主干上摘下来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-30\">三十 · 时延与吞吐的取舍：批大小、分块与精度的三角</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-31\">三十一 · 流式输出与调度闭环：把拼接开销算进 SLO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-32\">三十二 · 分块重叠与批调度耦合时的边界条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-33\">三十三 · 从单卡放不下到切分：TP 切的是权重与激活，EP 切的是专家</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-34\">三十四 · PP 与 DP：流水线填的是气泡，数据并行填的是副本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-35\">三十五 · NVLink 5 与 NVSwitch：All-Reduce 走的是对称带宽，All-to-All 走的是对分带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-36\">三十六 · NIXL 传输：分离式预填/解码与跨节点 KV cache 搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-37\">三十七 · 通信什么时候成为瓶颈：三个可判定的条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-38\">三十八 · 并行切分在视频扩散里的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-39\">三十九 · 精度塌陷的触发链：从权重到像素的逐级放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-40\">四十 · OOM 的三条来路：激活峰值、KV cache 与解码缓冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-41\">四十一 · 批抖动与尾延迟：调度器看不见的成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-42\">四十二 · 静默降级：指标及格但语义已坏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-43\">四十三 · 监控分层与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-44\">四十四 · 诊断顺序：先定类，再定量，后定回滚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-45\">四十五 · 基准口径的三层解耦：模型、硬件、负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-46\">四十六 · 硬件档位与并行拓扑：为什么跨档位数字不可比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-47\">四十七 · batch、并发与流式：三个被混用的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-48\">四十八 · 指标定义与不可比清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-49\">四十九 · 数字怎么读：从机制反推可信度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-50\">五十 · 工程判断：把基准写成可复现的口径卡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-51\">五十一 · 迁移的第一道关：注意力形态决定搬运成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-52\">五十二 · VAE 解码器：迁移时最容易被低估的一段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-53\">五十三 · 分块与重叠：收益边界在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-54\">五十四 · 批量与流式：调度假设的移植性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-55\">五十五 · 规模上限：三个硬约束而非一个</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-56\">五十六 · 哪里不适用：三条明确的否定判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-video-diffusion-models-2022-sec-57\">五十七 · 迁移边界：什么能搬、什么必须重算、什么根本不该搬</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:542px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 541.9 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入后按视频帧序列切分为时空 token，进入时空注意力算子计算。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">注意力输出经 VAE 解码器还原为像素帧，解码阶段受显存与带宽约束。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">长视频按分块与重叠策略切分，块间重叠区域用于拼接与一致性保持。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">批量与流式输出按调度策略组织，KV cache 与显存占用随并发变化。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"459.9\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">精度方案在 NVFP4/FP8 间选择，失败模式与监控覆盖显存溢出与带…</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-video-diffusion-models-2022-sec-1\">一 · 现场：一条 8 秒 720p 请求在午夜排队</h3>\n<p>设想一个在线短视频生成服务：用户提交一段文本，期望在数秒内拿到 8 秒、720p、24fps 的成片。请求进入调度器后，先被切成帧序列，每帧再 patch 化为时空 token，送入时空注意力主干；注意力输出交给 VAE 解码器还原像素帧；成片按流式分片回传。这条链路在白天低并发时看起来顺畅，但到了夜间高峰，队列里同时压着几十条长视频请求，端到端延迟开始以秒为单位漂移。工程师打开监控面板，看到的第一现场不是算力打满，而是显存占用曲线贴着上限走、HBM 带宽利用率居高不下、VAE 解码阶段的耗时在总延迟里占比异常突出。</p>\n<p>这就是这篇论文出场时的问题现场：视频扩散推理不是“把图像扩散的 batch 调大”那么简单。它的计算主干由时空注意力和 VAE 解码构成，而这两段对显存与带宽的胃口远大于同规模图像任务。注意力公式本身没有变：</p>\n<div class=\"formula\">$$\\mathrm{Attn}(Q,K,V)=\\mathrm{softmax}\\left(\\frac{QK^{\\top}}{\\sqrt{d}}\\right)V,\\quad \\mathrm{Mem}\\propto N_{\\mathrm{frame}}\\cdot N_{\\mathrm{token}}\\cdot d$$</div>\n<p>但视频把 $N_{\\mathrm{frame}}$ 乘了进去。帧数一涨，QKV 张量、注意力中间矩阵、以及为反向之外的推理缓存都要按帧数线性放大。旧方案在这一步就开始失守：显存先于算力成为瓶颈，调度器被迫降低并发，吞吐随之塌陷。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-2\">二 · 旧方案的第一层：整段视频一次性进注意力</h3>\n<p>论文之前的主流推理栈，处理视频的最直接做法是把整段帧序列当作一个超长序列，一次性铺进时空注意力算子。机制上很朴素：所有帧的 token 拼成一个二维矩阵，做全局注意力，让每一帧都能看见其余所有帧。好处是时序一致性天然成立，不需要块间拼接；代价是显存占用随帧数线性增长，且注意力的中间激活无法被及时释放。</p>\n<p>具体代价落在三处。其一是显存：QKV 与 softmax 中间结果同时驻留，长视频请求会把单卡显存推到溢出边缘，失败模式表现为 OOM 或调度器拒绝入队。其二是带宽：注意力算子反复读写这些大张量，HBM 带宽成为事实上的节拍器，算力单元反而在等数据。其三是延迟：VAE 解码必须等整段注意力全部完成才能启动，端到端延迟被拉成一条长尾，流式输出无从谈起——用户在前几秒看不到任何画面。</p>\n<p>一个具体例子：当并发从个位数升到数十条 8 秒请求时，旧栈的调度器只能靠减小批大小来换显存余量，批大小一小，GPU 利用率下降，单位请求的摊销成本上升，吞吐与延迟同时恶化。这不是调参能救的，是链路结构决定的。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-3\">三 · 旧方案的第二层：分块但无重叠，拼接处露馅</h3>\n<p>为了压显存，工程上自然的下一步是把长视频切块，逐块做注意力与解码，再把块拼回去。这一步解决了显存峰值，却引入了新的工程债：块与块之间没有共享上下文，拼接边界出现时序跳变——运动轨迹在块边界断裂、光照与色调不连续。旧方案对此的处理往往是加大块尺寸或事后做平滑，前者把显存问题请回来，后者把一致性责任推给后处理，端到端延迟又多了一段。</p>\n<p>更隐蔽的代价在调度侧。分块意味着一条请求被拆成多个子任务，子任务之间有严格的先后依赖（后一块要参考前一块的拼接状态），调度器必须为每条请求维护块级状态机。并发一高，状态机与 KV cache 一起膨胀，显存占用不再只由单块决定，而由“在途块数 × 每块缓存”决定。流式输出此时才勉强可行，但块间等待让首帧时间与尾帧时间不对称，SLO 难以用单一阈值描述。</p>\n<p>伪代码层面，旧栈的走查大致是：按固定块长切分帧序列；对每块独立跑时空注意力；VAE 逐块解码；按顺序拼接输出。缺失的一环正是重叠区域——没有重叠，就没有块间一致性锚点，拼接只能靠运气与后处理。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-4\">四 · 旧方案的第三层：精度与 KV cache 的粗放管理</h3>\n<p>精度维度上，旧栈通常沿用图像扩散的默认精度档位，未针对视频的长序列特性做区分。注意力主干与 VAE 解码对数值稳定性的敏感度不同：前者在长序列 softmax 下容易累积误差，后者在像素还原阶段对量化噪声更敏感。统一精度意味着要么全程高精度、显存与带宽吃紧，要么全程低精度、解码质量下滑。NVFP4/FP8 的选择在旧栈里是一个全局开关，而不是按阶段、按张量粒度切换的策略，这直接限制了显存与带宽的腾挪空间。</p>\n<p>KV cache 侧同样粗放。视频请求的缓存需求随帧数与并发线性上升，旧栈缺少按请求生命周期回收与复用的策略，缓存常驻显存，挤压了批大小与并发上限。调度器在“多接一条请求”与“留足缓存余量”之间反复权衡，吞吐曲线呈现明显的锯齿。监控只覆盖 GPU 利用率与显存总量，缺少对带宽瓶颈与解码阶段耗时的分项观测，失败模式往往在 OOM 发生后才被定位。</p>\n<p>把这些代价放在一张表里，旧栈的结构性短板就清楚了：</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>旧栈做法</th><th>主要代价</th><th>失败模式</th></tr></thead><tbody><tr><td>时空注意力</td><td>整段一次性全局注意力</td><td>显存随帧数线性涨、带宽成节拍器</td><td>OOM、并发被迫下调</td></tr><tr><td>长视频</td><td>固定块长、无重叠</td><td>块间拼接跳变、块级状态机膨胀</td><td>时序不一致、SLO 长尾</td></tr><tr><td>VAE 解码</td><td>等整段注意力完成后启动</td><td>端到端延迟拉长、流式不可行</td><td>首帧时间不可控</td></tr><tr><td>精度</td><td>全局统一档位</td><td>显存与质量二选一</td><td>解码噪声或带宽吃紧</td></tr><tr><td>KV cache</td><td>常驻、缺少生命周期回收</td><td>挤压批大小与并发</td><td>吞吐锯齿、缓存溢出</td></tr></tbody></table>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-5\">五 · 为什么非改不可：三个不可回避的工程判断</h3>\n<p>第一个判断是显存与带宽已经取代算力成为主约束。在视频扩散推理里，时空注意力的计算量随帧数增长，但显存与带宽的增长更快，因为中间激活与缓存的驻留时间被拉长。继续在旧栈上堆算力，收益被带宽墙吃掉；必须从链路结构上减少驻留与搬运。</p>\n<p>第二个判断是流式输出与批量调度不可兼得于旧结构。用户要的是首帧尽快可见，调度器要的是高并发摊销成本，两者在“整段注意力完成才解码”的前提下直接冲突。要解开这个冲突，必须让解码与注意力在时间上重叠，让块级输出可以提前回传，而这要求分块策略自带一致性锚点——也就是重叠区域。</p>\n<p>第三个判断是精度必须按阶段治理。注意力主干与 VAE 解码对数值误差的容忍度不同，统一档位是把两个不同的问题绑在一起解。把 NVFP4/FP8 的选择下沉到阶段与张量粒度，才能在显存、带宽与解码质量之间做出可解释的权衡，而不是靠全局开关碰运气。</p>\n<p>这三点合起来，构成了这篇论文要回答的问题：推理链路需要一个把时空注意力、VAE 解码、分块与重叠、批量与流式输出、精度与显存管理串成闭环的工程框架，而不是在旧栈上做局部补丁。旧栈的每一层补丁都在把代价转移到下一层——压显存就牺牲一致性，保一致性就牺牲并发，提并发就牺牲延迟——直到某一层溢出。</p>\n<p>回到午夜那条排队请求：旧栈给出的答案是“等”，而工程上不可接受。论文的切入点是让这条请求在块级别流动起来，让重叠区域承担一致性，让解码与注意力交错，让精度按阶段切换。这些机制的具体形态属于后续部分的范围，此处只需确认问题现场的边界：显存与带宽是主约束，分块与重叠是必答题，批量与流式输出是调度约束，精度是治理手段而非开关。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-6\">六 · 在线短视频生成的显存墙：从整段一次性推理到分块重叠的代价迁移</h3>\n<p>设想一个面向内容平台的在线视频生成服务：用户提交一段文本提示，期望在数秒内拿到数秒长度的短视频，同时系统要维持多路并发与流式首帧返回。在这篇论文之前，推理栈的主流做法是把整段视频当作一个整体一次性送入时空注意力主干，注意力输出再整体交给 VAE 解码器还原像素帧。这条链路在短片段上尚可运转，一旦帧数上升就立刻撞上显存墙。核心矛盾可以写成一条缩放关系：<div class=\"formula\">$$\\mathrm{Attn}(Q,K,V)=\\mathrm{softmax}\\left(\\frac{QK^{\\top}}{\\sqrt{d}}\\right)V,\\quad \\mathrm{Mem}\\propto N_{\\mathrm{frame}}\\cdot N_{\\mathrm{token}}\\cdot d$$</div>注意力矩阵随帧数与 token 数呈二次增长，而激活与中间特征又必须与 VAE 解码器的输入对齐，显存占用沿帧数线性抬升、沿序列长度加速恶化。工程上的直接后果是批大小被迫压到极小，GPU 的算力利用率与显存带宽利用率同时塌陷——算力在等显存，而不是显存在等算力。</p>\n<p>这条旧路径的失效条件相当明确：当请求的视频长度超过单卡可容纳的激活上限时，整段推理根本无法启动，只能靠降分辨率、降帧率或截断时长来“适配”，而这直接损伤输出质量。更隐蔽的代价在 VAE 解码环节——解码器需要把注意力输出还原为像素帧，其输入特征与输出像素缓冲同时驻留显存，是端到端延迟中的重环节；材料未给出具体解码耗时，但从机制上看，解码阶段的显存与带宽压力与注意力主干叠加，使得端到端延迟难以通过增加并发来摊薄。批量与流式输出阶段同样受限：KV cache 与显存占用随并发上升，调度策略只能在“多接几路但每路更慢”与“少接几路但首帧更快”之间做取舍，SLO 阈值材料未给出，但这一取舍的结构性存在不依赖具体数字。</p>\n<p>旧方案的另一处边界在于它把“长视频”当成“更长的短片段”处理，缺乏块间一致性机制。一旦为了绕开显存墙而手工切段，相邻块在边界处出现内容跳变与风格漂移，拼接只能靠后处理补救，反而引入额外计算。这正是分块与重叠策略要解决的问题：重叠区域用于块间拼接与一致性保持，代价是重叠部分被重复计算、重复占用显存，收益与开销必须逐项权衡，不能只写“效果更好”。下表把旧整段方案与新分块方案在几个工程维度上对照，表中不填具体数值，只标出代价方向：</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>整段一次性推理</th><th>分块与重叠</th></tr></thead><tbody><tr><td>显存峰值</td><td>随帧数线性抬升，易溢出</td><td>按块封顶，重叠区额外占用</td></tr><tr><td>计算量</td><td>无重复计算</td><td>重叠区重复计算，块数越多开销越大</td></tr><tr><td>批大小</td><td>被迫压至极小</td><td>可提升，但受块调度约束</td></tr><tr><td>一致性</td><td>整段天然一致</td><td>依赖重叠拼接，边界需处理</td></tr><tr><td>失败模式</td><td>显存溢出，请求直接失败</td><td>拼接瑕疵与带宽瓶颈</td></tr></tbody></table>\n<p>从系统代价看，旧方案把压力全部堆在单次前向的显存峰值上，缺乏任何可退让的旋钮；而分块与重叠把显存压力转化为计算与拼接开销，并让 NVFP4/FP8 精度选择成为可调变量——精度模式影响解码质量与显存占用，切换阈值材料未给出，但精度与显存的耦合是确定的。监控必须同时覆盖显存占用与吞吐，失败模式集中在显存溢出与带宽瓶颈两处。换言之，非改不可的理由不是“新方案更好”，而是旧方案在长视频与并发场景下没有可用的降级路径：一旦显存溢出，请求直接失败，调度层无从补救；而分块重叠至少把失败从“整段崩掉”降级为“边界瑕疵”，代价是可计算的重复算力与拼接开销。</p>\n<h3 id=\"paper-video-diffusion-models-2022-sec-7\">七 · 负载的四个可测维度：把“请求”拆成可记账的量</h3>\n<p>视频扩散的请求不是一个标量，而是一个四元组：帧数 <em>N</em><sub>frame</sub>、每帧时空 token 数 <em>N</em><sub>token</sub>、通道/嵌入维 <em>d</em>、以及请求到达时刻与期望完成时刻。前三个决定单请求的计算与显存，第四个决定排队与 SLO。工程上必须把这三者先落到测量口径上，否则“负载”只是形容词。可核查的口径是：以时空 token 总数 <em>S</em> = <em>N</em><sub>frame</sub> · <em>N</em><sub>token</sub> 作为长度代理量，按分位数（p50/p90/p99）统计其分布，而不是只报均值——视频请求的长度分布是典型的重尾，均值会把长视频的代价摊薄到看不见。</p>\n<p>与之配套的第二个口径是“有效 token 数”：长视频走分块与重叠策略时，重叠区域被重复计算，实际送入注意力算子的 token 数大于 <em>S</em>。设分块数为 <em>B</em>、重叠长度为 <em>L</em><sub>ov</sub>，则有效计算量近似为</p>\n<div class=\"formula\">$$S_{\\mathrm{eff}} \\approx S + (B-1)\\cdot L_{\\mathrm{ov}},\\qquad \\mathrm{Mem}\\propto S_{\\mathrm{eff}}\\cdot d$$</div>\n<p>这个式子给出一个直接可测的比值 <em>S</em><sub>eff</sub>/<em>S</em>，它是分块策略的“税”。测量口径要求同时记录 <em>S</em> 与 <em>S</em><sub>eff</sub>，否则吞吐数字会把重叠开销藏进分母。第三个口径是并发度：同时在飞的请求数 <em>C</em>，以及它与 KV cache 占用、显存水位的关系。第四个是 SLO 口径，必须写明是首帧时延（TTFF）、整段完成时延，还是流式输出下的帧间间隔（ITI）——三者对调度策略的要求完全不同，混用会让容量规划失真。</p>\n<p>具体例子：一个 8 秒、24fps 的请求与一个 2 秒、24fps 的请求，在 <em>N</em><sub>token</sub> 与 <em>d</em> 相同的前提下，<em>S</em> 相差四倍；若前者被切成 4 块、重叠占比 10%，则 <em>S</em><sub>eff</sub>/<em>S</em> 约为 1.3，意味着这个请求的注意力计算与显存占用比“名义长度”高约三成。容量规划若只按 <em>S</em> 算，长视频一进来就会撞显存墙。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-8\">八 · 并发与批大小：KV cache 是真正的约束面</h3>\n<p>批处理在视频扩散里不是免费的吞吐杠杆。每增加一个并发请求，KV cache 与中间激活按 <em>S</em><sub>eff</sub> · <em>d</em> 的量级增长，而 VAE 解码阶段的像素级缓冲又按 <em>N</em><sub>frame</sub> · 分辨率增长。于是批大小 <em>Bs</em> 的上界由显存水位反解：</p>\n<div class=\"formula\">$$Bs_{\\max}\\approx\\left\\lfloor\\frac{M_{\\mathrm{free}}-M_{\\mathrm{fix}}}{M_{\\mathrm{req}}}\\right\\rfloor,\\qquad M_{\\mathrm{req}}\\propto S_{\\mathrm{eff}}\\cdot d+N_{\\mathrm{frame}}\\cdot \\mathrm{res}$$</div>\n<p>其中 <em>M</em><sub>fix</sub> 是权重与算子工作区，<em>M</em><sub>req</sub> 是单请求峰值占用。这个式子的工程含义是：批大小不是一个可以“调大试试”的参数，而是被最长请求的 <em>M</em><sub>req</sub> 卡死的。混合长度批里，短请求被迫按长请求的显存预算排队，形成“长度污染”。可核查的测量口径是记录每批的 max(<em>S</em><sub>eff</sub>) 与批内方差，以及因显存不足被拒绝或降级的请求比例。</p>\n<p>流式输出把这个问题再推一步：解码阶段逐帧吐出，KV cache 必须驻留到该请求结束，无法像离线批那样整批释放。于是并发 <em>C</em> 与流式帧率构成一对矛盾——提高 <em>C</em> 摊薄权重读取带宽，却拉长单请求的驻留时间，抬高显存水位。代价落在延迟上：排队时延随 <em>C</em> 超线性上升，因为显存逼近上限时调度器被迫串行化长请求。具体例子：在同一显存预算下，把批大小从“按均值长度”改为“按 p90 长度”配置，短请求的排队时间下降，但长请求的批次数增加、权重重复读取次数上升，带宽开销变大——这是负载形态与方案互相塑造的第一个闭环。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-9\">九 · 长尾：p99 请求决定容量，而不是均值</h3>\n<p>视频请求的长尾有两个来源：超长视频（帧数远超常规）与超高分辨率（<em>N</em><sub>token</sub> 与 <em>d</em> 同时抬升）。这两类请求的 <em>M</em><sub>req</sub> 可能数倍于 p50，直接决定 <em>Bs</em><sub>max</sub> 的下界。若按均值做容量规划，p99 请求到达时系统要么 OOM，要么触发降级（减帧、降分辨率、减步数），而任何降级都会改变输出质量，属于 SLO 违约而非“优雅退化”。可核查口径：统计 p99 请求的 <em>S</em><sub>eff</sub> 与 p50 的比值，以及 p99 请求的端到端时延相对其 SLO 的超出量；同时记录降级触发率。</p>\n<p>长尾还通过分块策略放大：长视频必须分块，块数 <em>B</em> 随帧数线性增长，重叠开销 <em>(B−1)·L</em><sub>ov</sub> 也随之增长，于是 p99 请求的有效计算量不是线性而是近似“线性加常数项”地膨胀。工程判断是：对长尾请求单独设一条通道——要么预留显存配额，要么在准入控制层做长度分桶，把相近 <em>S</em><sub>eff</sub> 的请求编入同一批，减少“长度污染”带来的显存浪费。代价是调度复杂度上升与批利用率下降，需要在吞吐与尾延迟之间显式取舍。</p>\n<p>具体例子：一个 p99 请求的 <em>S</em><sub>eff</sub> 是 p50 的三倍，若它与若干 p50 请求同批，整批的显存峰值由它决定，其余请求的显存预算被闲置；改为分桶后，p50 桶的批大小可以更大，权重读取摊薄，但 p99 桶单独成批、批大小受限，其端到端时延上升。这个取舍必须用测量数据说话，而不是拍脑袋。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-10\">十 · SLO 口径：三种时延不可混用</h3>\n<p>视频扩散的 SLO 至少有三条互不等价的曲线：首帧时延（从请求到第一帧可看）、整段完成时延（到最后一帧）、流式帧间间隔（相邻帧的吐出间隔）。首帧时延由预填与初始去噪步决定，受 <em>S</em><sub>eff</sub> 与批大小影响；整段完成时延还叠加了 VAE 解码与拼接开销；帧间间隔则受解码阶段显存带宽与 KV cache 驻留约束。把三者混成一个“平均延迟”指标，会让调度器在首帧与尾帧之间做出错误权衡。</p>\n<p>可核查的测量口径要求分别记录：TTFF 的 p50/p99、整段完成时延的 p50/p99、ITI 的抖动（相邻间隔的标准差或 p99 间隔）。SLO 违约的判定必须绑定具体口径，例如“TTFF p99 ≤ 阈值”与“整段完成 p99 ≤ 阈值”是两条独立约束。工程上常见的失败模式是：为压 TTFF 而增大批大小，结果整段完成时延因显存逼近上限而恶化；或为压 ITI 抖动而减小批，吞吐下降导致排队时延上升。这两者都是负载形态与调度策略互相塑造的直接体现。</p>\n<p>具体例子：流式输出场景下，若 ITI 的 p99 抖动超过 SLO，用户体验是“卡顿”而非“慢”，此时应优先稳定解码阶段的显存带宽占用（例如限制并发解码的请求数），而不是提高整体吞吐。这个判断只能靠分口径测量得出，均值指标对此完全失明。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-11\">十一 · 方案反过来限制负载：准入控制与降级策略</h3>\n<p>负载塑造方案，方案也塑造负载。当显存与带宽成为硬约束时，系统必须通过准入控制反向裁剪负载形态：拒绝超长请求、要求客户端分段提交、或对长视频强制分块并限制重叠比例。这些策略改变了“请求”本身的定义，也就改变了测量口径——被拒绝的请求不计入时延统计，但必须计入拒绝率，否则容量规划会系统性乐观。</p>\n<p>可核查的口径包括：准入拒绝率（按 <em>S</em><sub>eff</sub> 分桶）、降级触发率（减帧/降分辨率/减步数各自的比例）、以及降级后输出与未降级输出的可感知差异（定性记录，材料未给出量化阈值）。工程判断是：降级策略必须与 SLO 口径绑定，例如“整段完成时延超阈值时允许减步数，但 TTFF 不得降级”，否则降级会悄悄破坏首帧体验。</p>\n<p>具体例子：当 p99 请求的 <em>M</em><sub>req</sub> 超过单卡显存预算时，系统可将其拆为多个分块请求串行提交，代价是块间拼接开销与总时延上升；或将其路由到预留配额通道，代价是常规通道的批大小下降。两种方案对吞吐与尾延迟的影响方向相反，必须用分桶测量数据选择，而不能靠“一般来说长视频少”这种无口径的判断。</p>\n<p>精度选择在这里也构成反向约束：NVFP4/FP8 影响解码质量与显存占用，切换阈值若按请求长度设定，就等于用精度换显存、再用显存换批大小。这条链路的每一环都需要独立测量——精度切换后的质量差异（定性）、显存占用变化、批大小上限变化、以及端到端时延变化——否则无法判断净收益。材料未给出具体阈值，故此处只保留机制性描述与测量口径要求。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-12\">十二 · 测量口径清单：可复核的最小集合</h3>\n<p>把上述内容收敛成一份可复核的清单，是本部分对工程读者的直接交付。每条都要求记录分位数而非均值，并要求同时记录分子与分母，防止指标被稀释。</p>\n<table class=\"mini\"><thead><tr><th>口径</th><th>定义</th><th>为何必须分桶</th></tr></thead><tbody>\n<tr><td>长度分布</td><td><em>S</em> = <em>N</em><sub>frame</sub>·<em>N</em><sub>token</sub> 的 p50/p90/p99</td><td>重尾，均值掩盖长视频代价</td></tr>\n<tr><td>有效计算比</td><td><em>S</em><sub>eff</sub>/<em>S</em>，含重叠开销</td><td>分块策略的“税”，随 <em>B</em> 增长</td></tr>\n<tr><td>并发与显存</td><td><em>C</em> 与显存水位的时序曲线</td><td>流式输出下 KV cache 驻留</td></tr>\n<tr><td>批内长度方差</td><td>每批 max(<em>S</em><sub>eff</sub>) 与方差</td><td>长度污染导致显存浪费</td></tr>\n<tr><td>TTFF / 整段 / ITI</td><td>三条独立时延曲线的 p50/p99</td><td>混用会误导调度权衡</td></tr>\n<tr><td>拒绝率与降级率</td><td>按 <em>S</em><sub>eff</sub> 分桶统计</td><td>被拒请求不计入时延，容量规划需校正</td></tr>\n</tbody></table>\n<p>这份清单的工程价值在于：它把“负载形态”从描述性词汇变成可记账的量，使得方案选择（分块大小、重叠比例、批大小、精度模式、准入策略）的每一次调整都能落到具体口径的变化上。材料未给出具体阈值与硬件档位，故清单只规定“测什么、怎么分桶”，不规定“阈值是多少”——阈值必须由部署方在自己的硬件与 SLO 下实测确定。</p>\n<p>最后落到一个具体机制上：分块与重叠策略的参数选择，本质是在 <em>S</em><sub>eff</sub>/<em>S</em> 与块间拼接开销之间求平衡。重叠越长，拼接一致性越好，但 <em>S</em><sub>eff</sub> 越大、显存与带宽代价越高；重叠越短，计算省了，但块间伪影风险上升。这个平衡点不能靠定性判断，必须用“有效计算比—拼接质量—端到端时延”三条口径的联合测量来定位，而这正是负载形态与方案互相塑造的最终落点。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-13\">十三 · 负载画像如何反向锁死视频扩散的部署边界</h3>\n<p>视频扩散的请求形态不是“一条 prompt 一个视频”这么简单：帧序列长度、分辨率与时长共同决定时空 token 规模，而 <span class=\"formula\">$$\\mathrm{Mem}\\propto N_{\\mathrm{frame}}\\cdot N_{\\mathrm{token}}\\cdot d$$</span> 意味着显存占用随帧数线性放大。于是负载分布的第一根刺是长尾——少数长视频请求单独就能吃掉整卡显存，迫使调度器在准入阶段就按分块与重叠策略切分，重叠区域用于块间拼接却带来额外计算与显存开销。测量口径必须可核查：按请求记录帧数、切块数、重叠帧数、单块峰值显存与拼接阶段额外耗时，而不是只报端到端平均延迟。批大小在这里不是自由变量，它被最长请求的显存足迹反向约束：一个长尾请求进入批内，整批的 KV cache 与激活占用按最大者对齐，短请求被迫陪跑。</p>\n<p>并发与流式输出把矛盾推到调度层。KV cache 与显存占用随并发上升，流式输出要求按块交付像素帧，VAE 解码器还原像素阶段又受显存与带宽约束，是端到端延迟的重要环节。若把 SLO 定义为“首块可播放时间”与“块间间隔抖动”两个口径，则批调度必须在吞吐与抖动之间取舍：增大批提高时空注意力算子的利用率，却拉长单请求的块间间隔。可核查的测量应分别记录批内请求数、批内最长帧数、VAE 解码排队时长与显存水位，避免用平均吞吐掩盖长尾请求的 SLO 违约。精度选择 NVFP4/FP8 也在此处变成负载约束：精度切换改变显存占用与解码质量，切换阈值未给出，工程上只能按显存水位与质量回归双口径监控。</p>\n<p>方案反过来限制负载，体现在失败模式上。显存溢出与带宽瓶颈是两类主要失效，监控需覆盖显存占用与吞吐；一旦分块重叠比例调大以保一致性，额外计算与拼接开销会推高单请求显存，反过来压低可接纳并发，形成“质量换容量”的闭环。因此容量规划不能只看平均帧数，而应按分位数帧长做准入裁剪：超过阈值的请求强制走更细分块或排队降级，阈值本身需由实测显存水位与 SLO 违约率标定，材料未给出具体数字，只能落到机制判断——负载塑造方案，方案又以准入与分块策略反过来裁剪负载的长尾。</p>\n<h3 id=\"paper-video-diffusion-models-2022-sec-14\">十四 · 时空注意力的 kernel 形状与精度落点</h3>\n<p>视频扩散的时空注意力在推理侧不是一个规整的 GEMM，而是一组形状随帧数、token 数与头维度变化的批量矩阵乘。设一次请求切成 $N_{\\mathrm{frame}}$ 帧、每帧 $N_{\\mathrm{token}}$ 个 token、头维度 $d$，则单头注意力的计算量与中间张量规模可写成：</p>\n<div class=\"formula\">$$\\mathrm{Attn}(Q,K,V)=\\mathrm{softmax}\\left(\\frac{QK^{\\top}}{\\sqrt{d}}\\right)V,\\quad \\mathrm{Mem}\\propto N_{\\mathrm{frame}}\\cdot N_{\\mathrm{token}}\\cdot d$$</div>\n<p>逐项解释：$QK^{\\top}$ 产生一个 $N_{\\mathrm{frame}}N_{\\mathrm{token}}\\times N_{\\mathrm{frame}}N_{\\mathrm{token}}$ 的分数矩阵，它是显存与带宽的第一大头；$\\sqrt{d}$ 的缩放必须在累加之后、softmax 之前施加，否则 FP8 下的指数输入会偏移；softmax 的输出再与 $V$ 相乘，这一步的累加精度直接决定注意力输出的低位有效位。工程上这意味着：分数矩阵不适合以 FP8 落盘再读回，而应在片上以更高精度完成缩放与 softmax，只把 $Q$、$K$、$V$ 的载入做成低精度。Blackwell 的 tcgen05 指令族正是为此设计——矩阵乘在 Tensor Core 内完成，累加器驻留 TMEM，softmax 与缩放可以在不把分数矩阵写回 HBM 的前提下就地处理。代价是 TMEM 容量有限，头维度与 tile 形状必须与 TMEM 分区对齐，否则会退化为多次 kernel 启动，端到端延迟被启动开销吃掉。</p>\n<p>具体例子：长视频分块时，若把重叠区域也当作独立 token 送入注意力，分数矩阵的行数随重叠长度线性增长，显存峰值随之抬升；把重叠帧的 $K/V$ 复用为块间共享的只读片段，可避免重复计算 $QK^{\\top}$，但要求 kernel 支持非连续 K/V 视图。这是形状问题，不是精度问题，却决定了低精度能否真正省下带宽。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-15\">十五 · 数据类型的分层：FP16/BF16、FP8、NVFP4</h3>\n<p>视频扩散推理的数值精度不是单一选择，而是按张量角色分层。VAE 解码器的卷积与上采样对低位宽敏感，像素还原阶段的舍入误差会直接表现为块状伪影与帧间闪烁；时空注意力的 $Q/K/V$ 投影与输出投影则相对耐受，因为 softmax 的归一化会吸收一部分量化扰动。BF16 的指数位宽与 FP16 相同但尾数更短，在激活动态范围大的层更稳；FP16 在尾数上更细，适合权重与需要精细累加的路径。</p>\n<p>FP8 分两种格式：E4M3 尾数多、动态范围窄，适合权重与激活；E5M2 动态范围宽、尾数少，适合梯度类或动态范围不可控的张量。推理侧通常把权重与激活都压到 E4M3，用 per-tensor 或 per-channel 缩放因子把值域映射进可表示区间，累加仍在 FP32 或更高精度完成。NVFP4 进一步把尾数压到 4 位，配合块级缩放（每若干元素共享一个指数），其收益主要在显存占用与 HBM 读带宽，而非 Tensor Core 峰值——因为 4 位输入的矩阵乘需要更频繁的反量化与缩放应用，若缩放粒度与 tile 不对齐，反而增加片上搬运。</p>\n<table class=\"mini\"><thead><tr><th>张量角色</th><th>推荐精度</th><th>主要代价</th></tr></thead><tbody><tr><td>VAE 解码卷积/上采样</td><td>FP16 或 BF16</td><td>低位宽导致像素级伪影，解码延迟受带宽约束</td></tr><tr><td>注意力 Q/K/V 投影</td><td>FP8 E4M3</td><td>缩放因子失配引起分数矩阵偏移</td></tr><tr><td>注意力输出投影</td><td>FP8 或 BF16</td><td>累加精度不足时帧间一致性下降</td></tr><tr><td>权重常驻</td><td>NVFP4 块缩放</td><td>反量化开销与 tile 对齐要求</td></tr></tbody></table>\n<p>具体例子：批量与流式输出阶段并发上升，KV cache 占用随并发线性增长；把 K/V 缓存压到 FP8 可把缓存带宽减半，但缓存里的 K 若在写入时量化、读出时不再反量化到更高精度，softmax 的分数会系统性偏移，表现为长视频后段帧的色彩漂移。因此 KV cache 的低精度化必须与读出侧的反量化配对，不能只做写入侧压缩。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-16\">十六 · 累加精度与误差传播路径</h3>\n<p>低精度输入的矩阵乘，其误差来源分三层：输入量化误差、乘积累加舍入、以及缩放因子的表示误差。设输入 $x$ 被量化为 $\\hat{x}=s\\cdot q$，其中 $s$ 是缩放因子、$q$ 是整型码点，则单元素误差上界为 $|x-\\hat{x}|\\le s/2$；$K$ 维累加后的误差近似随 $\\sqrt{K}$ 增长（随机舍入假设下），而不是随 $K$ 线性增长。这解释了为什么长序列注意力更依赖 FP32 累加器：$K$ 越大，低位累加的偏差越容易被 softmax 放大。</p>\n<div class=\"formula\">$$\\hat{y}=\\sum_{k=1}^{K}\\hat{x}_k\\hat{w}_k,\\quad \\mathbb{E}\\left[(\\hat{y}-y)^2\\right]\\approx \\sigma_q^2\\sum_{k=1}^{K}(x_k^2+w_k^2)$$</div>\n<p>逐项解释：$\\sigma_q^2$ 是量化噪声方差，正比于缩放因子的平方；求和项说明误差随参与累加的元素能量增长。工程含义是：缩放因子应按通道或块自适应，使 $\\sigma_q^2$ 与张量能量匹配；累加器位宽不足时，大 $K$ 的注意力分数矩阵会出现系统性偏低，softmax 后注意力分布变平，视频帧间的运动一致性被削弱。</p>\n<p>具体例子：VAE 解码器的最后一层上采样若用 FP8 卷积且累加在 FP16 完成，输出像素的低位会被截断，暗部区域的渐变出现条带；把该层累加提升到 FP32、仅输入保持 FP8，条带消失而带宽收益保留。这说明“输入低精度、累加高精度”是可分离的两个决策，不能笼统称为“用 FP8 推理”。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-17\">十七 · Blackwell 的 tcgen05、TMEM 与 2-SM MMA</h3>\n<p>Blackwell 的第五代 Tensor Core 把矩阵乘的累加器从寄存器文件迁移到 TMEM（Tensor Memory），tcgen05 指令族以异步方式发起 MMA，累加结果留在 TMEM 中供后续 epilogue 读取。对视频扩散推理的直接意义是：注意力分数矩阵这类“算完即用、不落 HBM”的中间张量可以全程留在片上，省掉一次写回与一次读回的带宽。代价是 TMEM 是有限资源，多个并发请求的注意力 kernel 若同时驻留，TMEM 分区会争用，调度器必须限制同时在飞的 MMA 数量，否则 kernel 排队导致尾延迟抬升。</p>\n<p>2-SM MMA 让两个 SM 协作完成一次更大的矩阵乘 tile，等效于把单次 MMA 的 M 维或 N 维扩大，减少 tile 数量与启动次数。对时空注意力而言，分数矩阵的行维随帧数增长，2-SM 协作可以把大 tile 一次吃掉，降低 kernel 启动开销；但协作要求两个 SM 的 TMEM 与共享内存布局对齐，非规则的序列长度（分块与重叠造成的尾块）会让协作退化为单 SM 路径，收益消失。因此分块大小与重叠长度的选择不只是显存问题，也决定了 2-SM MMA 能否被有效利用。</p>\n<p>具体例子：长视频分块时若块大小为 2 的幂且与 tile 形状对齐，2-SM MMA 可覆盖整块；若重叠长度取非规则值，尾块只能走单 SM 路径，端到端延迟出现锯齿。工程判断是：重叠长度应按 tile 粒度向上取整，用少量冗余计算换取协作路径的稳定命中。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-18\">十八 · 精度切换的工程判据与监控落点</h3>\n<p>精度不是全局开关，而是按阶段与按张量切换的策略。可操作的判据有三条：其一，VAE 解码器的像素还原层保持 FP16/BF16 输入与 FP32 累加，因为伪影不可逆；其二，时空注意力的 $Q/K/V$ 载入用 FP8，softmax 与缩放用更高精度，累加器用 FP32；其三，KV cache 的低精度化必须成对配置写入量化与读出反量化，并以帧间一致性指标监控漂移。</p>\n<ul>\n<li>显存判据：KV cache 随并发线性增长，低精度化是唯一能在不降并发的前提下压住显存的手段，但需预留反量化缓冲。</li>\n<li>带宽判据：分数矩阵不落 HBM 依赖 TMEM 容量，TMEM 不足时退回 HBM 路径，带宽立刻成为瓶颈。</li>\n<li>质量判据：块间重叠区域的拼接一致性对量化误差最敏感，应作为精度回归的采样点。</li>\n</ul>\n<p>监控需覆盖显存占用峰值、TMEM 争用导致的 kernel 排队、以及低精度路径下的帧间一致性抽样。失败模式包括显存溢出与带宽瓶颈，材料未给出具体阈值，因此监控应以相对基线的漂移量而非绝对数值设警。具体例子：批量流式输出下并发抬升，若 KV cache 已压到 FP8 而反量化缓冲未预留，显存峰值反而高于 FP16 路径——压缩收益被缓冲抵消，这是精度策略必须与显存预算联合求解的原因。</p>\n<p>最终落在机制上：视频扩散推理的低精度收益来自“中间张量不落 HBM”与“KV cache 带宽减半”两条路径，前者依赖 tcgen05 与 TMEM 的片上驻留，后者依赖写入与读出成对的量化协议；任何一条路径缺少配对的反量化或 tile 对齐，收益都会被额外的搬运与排队吃掉。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-19\">十九 · 精度下探的边界：从 BF16 到 NVFP4 在时空注意力与 VAE 解码上的失效条件</h3>\n\n<p>视频扩散推理的精度选择不是全局开关，而是按算子分域的。时空注意力主干对 QK^T 的累加精度敏感：softmax 前的 logits 若在 FP8 下累加，帧间 token 的相似度分布会被压平，长程帧对帧的注意力权重趋同，表现为块间拼接处的闪烁；而 VAE 解码器的卷积与上采样对权重量化更敏感，激活动态范围在像素还原阶段被放大。工程上的可行切分是注意力矩阵乘走 FP8 输入配 FP32 累加，VAE 解码保留 BF16 权重、仅对激活做 FP8 量化，NVFP4 只用于显存带宽受限的中间特征驻留而非参与累加。代价是混合精度引入的类型转换 kernel 与额外显存副本，在分块重叠区域被反复触发，重叠长度越大，转换开销按重叠 token 数线性增长。</p>\n\n<div class=\"formula\">$$\\mathrm{Err}_{\\mathrm{acc}} \\approx \\frac{\\sqrt{N_{\\mathrm{acc}}}\\,\\epsilon_{\\mathrm{mant}}}{2\\sqrt{3}},\\quad \\mathrm{BW}_{\\mathrm{saved}} \\propto 1-\\frac{b_{\\mathrm{low}}}{b_{\\mathrm{high}}}$$</div>\n\n<p>第一项说明累加误差随累加链长度 N_acc 与尾数位宽 ε_mant 增长：时空注意力的累加链跨越帧数与 token 数，链越长，低精度累加的偏差越难被 softmax 的归一化吸收；第二项说明位宽从高精度降到低精度带来的带宽节省比例，但节省只在数据确实以低精度驻留显存时兑现，若每步都反量化回高精度计算，带宽收益被转换流量抵消。这解释了为什么 NVFP4 在视频扩散里更适合做 KV 或中间特征的存储格式，而非注意力计算的输入格式——存储侧省带宽，计算侧仍要 FP8/BF16 累加。系统代价落在显存与带宽的权衡上：低精度驻留降低峰值显存，允许更大分块或更高并发，但反量化 kernel 占用 SM 周期，与时空注意力争抢算力。</p>\n\n<p>Blackwell 的 tcgen05 与 TMEM 改变了这个权衡的形状。2-SM MMA 让两个 SM 协同完成一次大矩阵乘，累加器驻留 TMEM 而非寄存器堆，使 FP32 累加的长链不必反复溢出到共享内存；第五代 Tensor Core 对 FP8 与 NVFP4 的输入支持使低精度乘加在同一指令内完成，减少了显式反量化的中间步骤。但 TMEM 容量有限，时空注意力的分块必须按 TMEM 容量切分，块过大则累加器换出，块过小则 MMA 利用率下降。失效条件很具体：当分块重叠区域的 token 数超过单次 MMA 能容纳的 TMEM 行数时，重叠拼接被迫拆成多次小 MMA，累加精度虽保住，但 kernel 启动与同步开销吞掉带宽收益。工程判断是先用 BF16 跑通端到端链路、记录 VAE 解码与注意力的显存峰值，再按算子逐一试 FP8，NVFP4 只在确认反量化流量低于带宽节省时才启用；监控需覆盖显存占用、反量化 kernel 占比与块间拼接的一致性指标，任一越界即回退精度档位。</p>\n\n<table class=\"mini\"><thead><tr><th>算子域</th><th>可行精度组合</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>时空注意力 QK^T</td><td>FP8 输入 + FP32 累加</td><td>TMEM 容量约束分块</td><td>重叠 token 超 TMEM 行数</td></tr><tr><td>VAE 解码卷积</td><td>BF16 权重 + FP8 激活</td><td>激活反量化流量</td><td>像素还原动态范围溢出</td></tr><tr><td>中间特征驻留</td><td>NVFP4 存储</td><td>反量化 kernel 占 SM</td><td>转换流量高于带宽节省</td></tr></tbody></table>\n<h3 id=\"paper-video-diffusion-models-2022-sec-20\">二十 · 显存账本的三层结构：权重、激活、KV</h3>\n<p>视频扩散推理的显存不是一块整账，而是三本必须分开记的账：权重账、激活账、KV 账。三者的增长规律完全不同，混在一起算就会在容量规划上出错。权重账是静态的，由模型参数量与精度位宽决定，NVFP4 下每参数 4 bit、FP8 下 8 bit，加载后基本不变；激活账是动态的，随时空注意力的序列长度与批大小线性甚至平方增长；KV 账在扩散模型里是特殊的存在——它不是自回归 LLM 那种逐 token 追加的缓存，而是时空注意力在去噪步之间可复用的中间态，是否保留、保留几层、保留几个时间步，直接决定账本厚度。</p>\n<p>把三本账写成可复算的形式。设参数量为 \\(P\\)、权重位宽为 \\(b_w\\)、批大小为 \\(B\\)、每段视频的帧数为 \\(N_{\\mathrm{frame}}\\)、每帧 token 数为 \\(N_{\\mathrm{token}}\\)、隐藏维度为 \\(d\\)、层数为 \\(L\\)、KV 保留比例为 \\(\\rho\\)（0 到 1，表示被缓存的层或时间步占比）、KV 位宽为 \\(b_{kv}\\)，则：</p>\n<div class=\"formula\">$$\\mathrm{Mem}_{\\mathrm{total}} = \\underbrace{\\frac{P \\cdot b_w}{8}}_{\\text{权重}} + \\underbrace{B \\cdot N_{\\mathrm{frame}} \\cdot N_{\\mathrm{token}} \\cdot d \\cdot b_a / 8}_{\\text{激活}} + \\underbrace{\\rho \\cdot L \\cdot B \\cdot N_{\\mathrm{frame}} \\cdot N_{\\mathrm{token}} \\cdot d \\cdot 2 \\cdot b_{kv} / 8}_{\\text{KV}}$$</div>\n<p>公式里的 2 来自 K 与 V 两份。注意激活项没有乘层数，因为推理时逐层前向，同一时刻只有少数层的激活驻留；但时空注意力的注意力矩阵本身是 \\(N_{\\mathrm{frame}} \\cdot N_{\\mathrm{token}}\\) 的平方项，在长视频下会压过线性项，这是激活账最容易爆的地方。KV 项乘了层数 \\(L\\)，因为缓存是跨层保留的，这也是 KV 账在长视频下比激活账更危险的原因：激活可以逐层释放，KV 一旦保留就是常驻。</p>\n<p>工程代价落在具体环节上：权重账决定能否单卡装下、要不要做张量并行；激活账决定分块粒度与批大小上限；KV 账决定并发数与流式输出的可持续性。以一段中等长度视频为例，帧数取数十、每帧 token 取数百量级、维度取千级，激活项在 FP8 下已进入数十 GB 量级，KV 若按 \\(\\rho=0.5\\)、层数十余层保留，账本再翻一倍——此时单卡 HBM3e 容量成为硬约束，而不是算力。材料未给出具体帧数与 token 规模数字，上述量级仅用于说明账本结构，不作为实测值。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-21\">二十一 · 分页与压缩：把 KV 从连续块变成可管理页</h3>\n<p>扩散视频推理的 KV 与 LLM 的 PagedAttention 思路同源但动机不同。LLM 分页是为了解决变长序列的碎片化；视频扩散分页是为了解决时空注意力的<strong>块间重叠</strong>带来的重复驻留。长视频按分块与重叠策略切分时，重叠区域的 token 会被相邻两块同时引用，若每块各自持有一份连续 KV，重叠区就被复制了两次，显存账本里出现无法回收的冗余。分页把 KV 切成固定大小的页，块间共享页的引用计数，重叠区只存一份。</p>\n<p>伪代码思路如下：每个分块请求一组页号，页表按（层、时间步、帧区间）三维索引；拼接阶段按页号重组逻辑序列，重叠区的页引用计数加一，块释放时减一，归零才回收。代价是页表本身占显存（页大小越小、页表越大），以及拼接时的间接寻址带来额外带宽开销——注意力算子读 KV 从连续地址变成按页 gather，HBM 访问的合并度下降。</p>\n<p>压缩则是另一条路：KV 位宽从 FP8 降到 NVFP4，账本直接减半，但 NVFP4 的块缩放（block scaling）需要在每页内维护缩放因子，页内 token 分布不均时缩放因子失真会放大误差。工程判断是：压缩优先作用在<strong>时间维冗余高的层</strong>，即那些跨帧注意力贡献小的层，而不是均匀压所有层。材料未给出精度切换阈值与失败模式数字，故这里只给机制判断：压缩比与层选择必须联合调，单独调压缩比会在解码质量上出现不可控退化。</p>\n<p>带宽瓶颈在此处显形：分页后 KV 读取不再是顺序流，gather 的随机性使有效带宽低于峰值 HBM3e 带宽；压缩虽减半容量，但解压（缩放因子乘回）增加算力开销。二者叠加时，端到端延迟的瓶颈可能从容量转到带宽，再从带宽转到解压算力——这是三个不同的瓶颈位，监控必须分别覆盖。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-22\">二十二 · 复用与卸载：跨去噪步与跨块的两种时间尺度</h3>\n<p>复用发生在去噪步之间。扩散采样有数十步，相邻步的时空注意力输出高度相关，KV 在步间复用能省掉重复计算与重复驻留。但复用不是免费的：复用的 KV 是旧步的，与新步的 Q 做注意力时数值分布漂移，需要在复用比例与质量之间取舍。机制上，可按层设定复用步间隔，间隔越大省得越多、漂移越大；也可按帧区间设定，时间上稳定的帧区间复用、运动剧烈的区间不复用。材料未给出缓存命中率数字，故只保留机制描述。</p>\n<p>卸载发生在跨块与跨阶段。VAE 解码器还原像素帧阶段受显存与带宽约束，是端到端延迟的重要环节；解码时时空注意力的 KV 已无用，可卸载到主机内存或释放，把 HBM 让给解码器的激活。反向地，解码完成后像素帧写回时，下一段视频的时空注意力又要重新装载权重与 KV——卸载与重载之间的 PCIe/NVLink 传输成为新的延迟项。工程判断是：卸载的收益取决于传输带宽与计算重叠度，若卸载不能与下一块的计算重叠，省下的显存换来的延迟损失可能抵不过收益。</p>\n<p>复用与卸载共享一个约束：<strong>账本的可预测性</strong>。分页让 KV 的驻留位置可追踪，复用让驻留时间可延长，卸载让驻留位置可迁移——三者组合后，显存占用不再是静态峰值，而是随时间波动的曲线。容量规划必须按曲线的峰值而非均值做，否则在长视频流式输出下会在某个块边界处溢出。失败模式包括显存溢出与带宽瓶颈，监控需覆盖显存占用与吞吐，材料未给出具体阈值。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-23\">二十三 · 带宽瓶颈定位：HBM3e 容量与有效带宽的换算</h3>\n<p>HBM3e 的容量决定了账本上限，但真正决定延迟的是有效带宽而非峰值带宽。视频扩散推理的带宽消耗分布在三处：权重读取（每层前向读一次权重）、KV 读取（注意力每步读 KV）、激活写回（注意力输出与 VAE 解码的中间态）。三者的比例随批大小变化：批越大，权重读取被摊薄，KV 与激活占比上升；批越小，权重读取成为主项。这解释了为什么小批量下推理是带宽受限、大批量下是容量受限。</p>\n<p>把带宽账写成可复算形式。设单步前向的权重读取量为 \\(P \\cdot b_w / 8\\)、KV 读取量为 \\(\\rho \\cdot L \\cdot B \\cdot N_{\\mathrm{frame}} \\cdot N_{\\mathrm{token}} \\cdot d \\cdot 2 \\cdot b_{kv} / 8\\)、激活读写量为 \\(B \\cdot N_{\\mathrm{frame}} \\cdot N_{\\mathrm{token}} \\cdot d \\cdot b_a / 8\\) 的若干倍，则单步时间下界为：</p>\n<div class=\"formula\">$$T_{\\mathrm{step}} \\ge \\frac{\\mathrm{Bytes}_{\\mathrm{weight}} + \\mathrm{Bytes}_{\\mathrm{KV}} + \\mathrm{Bytes}_{\\mathrm{act}}}{\\mathrm{BW}_{\\mathrm{eff}}}$$</div>\n<p>其中 \\(\\mathrm{BW}_{\\mathrm{eff}}\\) 是有效带宽，受分页 gather、压缩解压、地址对齐影响，低于峰值。这个下界是容量规划的第一道筛子：若算出的 \\(T_{\\mathrm{step}}\\) 乘以步数已超过 SLO，则无论算力多强都无法达标，必须先降 KV 账或降激活账。工程上常见的错误是先扩算力再发现带宽打满，顺序反了。</p>\n<p>具体例子：一段长视频按分块切分后，单块内 KV 读取量随帧数线性增长，而权重读取量固定；当帧数增大到某一规模，KV 读取超过权重读取成为主项，此时提升批大小不再摊薄带宽，反而加剧 KV 读取——这就是长视频下批大小不能盲目放大的机制原因。材料未给出具体帧数与带宽数字，上述为结构性判断。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-24\">二十四 · 一个可复算的显存预算：从参数到容量判断</h3>\n<p>给出一个可复算的预算流程，读者可代入自己的模型参数复算。第一步，算权重账：参数量乘以位宽除以 8，NVFP4 与 FP8 各算一遍，得到两个容量下限。第二步，算激活账峰值：取批大小、帧数、每帧 token 数、维度，乘以激活位宽，再乘以注意力矩阵的平方项系数（长视频下该项主导），得到单层峰值，乘以同时在驻留的层数（通常远小于总层数）。第三步，算 KV 账：取保留比例、层数、批大小、序列长度、维度、KV 位宽，乘以 2。第四步，把三本账相加，与目标硬件的 HBM3e 容量比较，留出页表、缩放因子、框架运行时开销的余量。</p>\n<p>预算的敏感性分析比绝对值更有用。权重账对位宽线性敏感，NVFP4 相对 FP8 直接减半；激活账对帧数与 token 数敏感，且注意力平方项使其对序列长度超线性；KV 账对保留比例 \\(\\rho\\) 与层数敏感，\\(\\rho\\) 是唯一可以按层、按时间步精细调节的旋钮。工程判断是：当预算超限时，优先调 \\(\\rho\\) 与分块粒度，再调批大小，最后才动精度——因为精度切换影响解码质量，而 \\(\\rho\\) 与分块只影响复用策略。</p>\n<p>表格给出三本账的调节旋钮与代价方向：</p>\n<table class=\"mini\"><thead><tr><th>账本</th><th>主旋钮</th><th>容量收益</th><th>代价</th></tr></thead><tbody><tr><td>权重</td><td>位宽 NVFP4/FP8</td><td>线性减半</td><td>解码质量退化，需数值稳定验证</td></tr><tr><td>激活</td><td>分块大小、批大小</td><td>分块减小则峰值降</td><td>重叠区拼接开销上升，块间一致性代价</td></tr><tr><td>KV</td><td>保留比例 \\(\\rho\\)、分页、压缩</td><td>\\(\\rho\\) 降则线性降</td><td>复用命中下降、gather 带宽损失、解压算力</td></tr></tbody></table>\n<p>这张表的关键在于代价列不是零：每一本账的缩减都在别处产生开销，预算不是单向压缩而是三方权衡。材料未给出具体数据规模与阈值，故表格只给方向不给数字。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-25\">二十五 · 失败模式与监控落点</h3>\n<p>显存账本失控的失败模式有三类，各自的监控落点不同。第一类是容量溢出：三本账之和在某个块边界越过 HBM3e 容量，表现为分配失败或强制换页，监控落在显存占用的峰值曲线与块边界时刻。第二类是带宽打满：有效带宽被分页 gather 与解压拖低，单步时间下界被突破，监控落在 KV 读取的有效带宽与注意力算子利用率。第三类是复用漂移：KV 复用比例过高导致解码质量退化，监控落在复用步间隔与输出帧的一致性指标上——这类失败不报错，只降质，最容易被漏掉。</p>\n<p>三类失败共享一个工程判断：账本必须按<strong>时间曲线</strong>监控而非按静态峰值。分块与重叠使显存占用呈锯齿状，复用使 KV 驻留时间拉长，卸载使占用在阶段间跳变；只看一个峰值数字会掩盖块边界的瞬时溢出。监控的最小集合是：显存占用随时间、KV 有效读取带宽、复用命中比例与复用步间隔、VAE 解码阶段的显存与带宽占用。材料未给出具体监控指标与阈值，故此处只给指标集合不给阈值。</p>\n<p>最后落在具体机制上：当预算超限且无法靠 \\(\\rho\\) 与分块解决时，正确的动作是把 KV 账从常驻改为分页加卸载的组合——分页保证重叠区不复制，卸载保证解码阶段让出 HBM，两者叠加把峰值从“权重+激活+全量 KV”降到“权重+激活+当前块 KV”。这个动作的代价是页表开销与卸载传输延迟，收益是容量上限的实质抬升；是否值得，取决于卸载能否与下一块计算重叠，这是容量规划里唯一需要实测的环节，其余都可由上面的公式复算。</p>\n<h3 id=\"paper-video-diffusion-models-2022-sec-26\">二十六 · 从“整段生成”到“可调度单元”：扩散去噪步的批处理边界</h3>\n<p>视频扩散推理与自回归 LLM 推理在调度上的根本差别在于：一次请求不是“一次前向 + 逐 token 解码”，而是固定步数的去噪迭代，每步都是一次完整的时空注意力 + VAE 侧特征更新。因此连续批处理（continuous batching）在扩散场景里不能照搬 token 级迭代粒度，必须以“去噪步”为调度原子。工程上的做法是把请求拆成 (request_id, step_index, chunk_id) 三元组，调度器在每个去噪步边界重新组批：已完成第 t 步的请求留在批内继续第 t+1 步，新到达请求在步边界插入。这样做的代价是批内请求的步数进度不一致，时空注意力的序列长度因分块不同而不同，组批时必须按最大 token 数填充，浪费算力。</p>\n<p>设批内有 $B$ 个请求，第 $i$ 个请求当前步的 token 数为 $n_i$，填充到 $\\max_i n_i$ 后的有效计算占比为：</p>\n<div class=\"formula\">$$\\eta=\\frac{\\sum_{i=1}^{B} n_i}{B\\cdot \\max_i n_i}$$</div>\n<p>当分块大小差异大时 $\\eta$ 迅速下降，这正是视频扩散连续批处理比 LLM 更难的原因：LLM 的 token 长度差异可以用 chunked prefill 抹平，而视频分块的 token 数由帧数与分辨率决定，填充浪费直接体现为时空注意力的算力空转。具体例子：一批内混有 480p 短片段与 720p 长片段，若不做长度分桶，$\\eta$ 会被长片段拉低，GPU 的 tensor core 利用率随之下降。工程判断是：连续批处理在视频扩散里必须与长度分桶（length bucketing）联合设计，否则吞吐收益被填充开销吃掉。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-27\">二十七 · Chunked prefill 的扩散变体：把分块与重叠纳入预填调度</h3>\n<p>LLM 的 chunked prefill 是把长 prompt 切成若干 chunk 分批送入，避免单次 prefill 撑爆显存并让解码请求插队。视频扩散的对应物是长视频分块与重叠：一个长视频请求被切成若干块，块间保留重叠区域用于拼接与一致性保持。调度器可以把这些块当作独立的 prefill 单元排队，与已在去噪中的请求共享批空间。关键机制是重叠区的重复计算：重叠长度 $L_{\\mathrm{ov}}$、块长 $L_{\\mathrm{ch}}$ 时，总计算量为 $N_{\\mathrm{blk}}\\cdot (L_{\\mathrm{ch}}+L_{\\mathrm{ov}})$，相对无重叠的 $N_{\\mathrm{blk}}\\cdot L_{\\mathrm{ch}}$ 多出比例：</p>\n<div class=\"formula\">$$\\rho=\\frac{L_{\\mathrm{ov}}}{L_{\\mathrm{ch}}}$$</div>\n<p>这部分额外计算是显存收益的对价：重叠区让块间拼接不必回读全部历史帧，降低峰值显存与带宽压力。调度上的取舍是——重叠越长，拼接质量越稳，但 $\\rho$ 越大，chunked prefill 队列的有效吞吐越低。具体例子：一个长视频请求被切成多块进入 prefill 队列，若重叠比例偏高，队列中每块的注意力计算量上升，尾延迟被拉长；若重叠过短，块间拼接出现闪烁，需要重跑。工程上把重叠长度作为可调参数暴露给调度器，按 SLO 在质量与吞吐间切换，而不是固定常量。</p>\n<p>另一个机制是块间依赖：第 k 块的去噪需要第 k−1 块的重叠区特征作为条件，这形成流水线依赖。调度器必须保证同一请求的块按序推进，不能像 LLM 那样任意插队，否则重叠区特征尚未就绪。代价是同一请求的块在批内占据连续步位，降低了跨请求的组批灵活性。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-28\">二十八 · 优先级与抢占：尾延迟从哪里来，怎么压</h3>\n<p>视频扩散的尾延迟（tail latency）主要来自三类长请求：长视频多分块请求、高分辨率请求、以及 VAE 解码阶段显存吃紧导致的排队。优先级调度要区分“步内优先级”和“请求级优先级”。请求级优先级按 SLO 剩余时间排序，步内优先级决定批内顺序。抢占（preemption）在扩散里的实现不是丢弃 KV，而是把请求的中间去噪状态（当前步的 latent 与重叠区特征）换出到主机内存或低带宽显存池，释放设备显存给高优先级请求。换出代价是带宽：latent 张量大小与帧数、token 数、维度成正比，换出一次就是一次显存—主机往返。</p>\n<p>尾延迟的压缩靠两个手段：一是对长请求做“步数配额”，在 SLO 窗口内只允许推进若干步，剩余步延后到下一窗口，避免单个长请求垄断批空间；二是对 VAE 解码做分离调度，把解码阶段从去噪批中剥离，单独组批以平滑显存峰值。具体例子：一个高优先级短请求与一个低优先级长视频请求同批，若不抢占，短请求的尾延迟被长请求的分块步数拖长；启用状态换出后，长请求让出显存，短请求在 SLO 内完成，长请求在下一窗口续跑。代价是长请求的端到端延迟变长，这是显式的取舍，不是免费的。</p>\n<p>监控上要盯的不是平均延迟，而是 P99 与抢占次数：抢占次数上升说明批空间不足或优先级配置过激，P99 上升说明尾请求的步数配额不合理。材料未给出具体阈值，工程上以“抢占率”和“换出带宽占比”作为两个可观测信号。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-29\">二十九 · 分离式预填/解码：把 VAE 解码从去噪主干上摘下来</h3>\n<p>分离式预填/解码（disaggregated prefill/decode）在 LLM 里是把 prefill 与 decode 放到不同实例，避免两种负载互相干扰。视频扩散的对应切分是：时空注意力去噪主干（计算密集、显存带宽双高）与 VAE 解码器（显存带宽密集、计算相对轻）分到不同资源池。去噪池追求高 tensor core 利用率与大批量，解码池追求高带宽与低排队。两池之间通过 latent 张量传输衔接，传输量正比于 $N_{\\mathrm{frame}}\\cdot N_{\\mathrm{token}}\\cdot d$，这正是分离的带宽代价。</p>\n<p>分离的收益在于解耦显存峰值：去噪阶段的 KV cache 与重叠区特征占用设备显存，VAE 解码阶段的像素帧还原又需要额外显存，两者叠加会触发显存溢出。分离后，解码池按自己的节奏消费 latent，去噪池不必为解码预留显存。具体例子：长视频请求在去噪池完成全部去噪步后，latent 经 NVLink 传到解码池，解码池按帧批次流式输出像素帧；若两池同机，传输走 NVLink 5，带宽足够但增加一跳延迟；若跨机，传输成为端到端延迟的显式项。工程判断是：分离的粒度取决于 latent 传输量与解码显存峰值的比值，传输量小、解码显存峰值高时分离收益最大。</p>\n<p>调度上，分离式架构要求两池的批处理节奏匹配：去噪池产出 latent 的速率与解码池消费速率不一致时，中间队列积压，尾延迟上升。因此两池需要共享一个背压信号，解码池队列深度超过阈值时反向抑制去噪池的批大小。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-30\">三十 · 时延与吞吐的取舍：批大小、分块与精度的三角</h3>\n<p>视频扩散推理的吞吐—时延曲线由三个变量共同决定：批大小 $B$、分块重叠比例 $\\rho$、精度模式（NVFP4/FP8）。批大小提升吞吐但拉长单请求排队时间；$\\rho$ 提升拼接质量但增加计算量；精度降低显存占用与带宽压力但影响解码质量。三者不是独立的，精度切换会改变显存预算，进而改变可容纳的批大小与分块大小。设显存预算为 $M$，单请求显存占用近似正比于 $N_{\\mathrm{frame}}\\cdot N_{\\mathrm{token}}\\cdot d\\cdot b_{\\mathrm{prec}}$，$b_{\\mathrm{prec}}$ 为每元素字节数，则可容纳批大小：</p>\n<div class=\"formula\">$$B_{\\max}\\approx \\frac{M}{N_{\\mathrm{frame}}\\cdot N_{\\mathrm{token}}\\cdot d\\cdot b_{\\mathrm{prec}}}$$</div>\n<p>NVFP4 相对 FP8 把 $b_{\\mathrm{prec}}$ 减半，$B_{\\max}$ 翻倍，但解码质量需要验证，材料未给出精度切换阈值。工程上的做法是把精度作为调度维度：高优先级短请求走 FP8 保质量，低优先级长请求走 NVFP4 保吞吐，同一批内不混精度以避免 kernel 切换开销。具体例子：流式输出场景下，用户期望逐帧到达，批大小不能无限增大，否则首帧延迟被批内其他请求拖长；此时应降低批大小、提高分块并行度，用更多块并行换取首帧时间。这是时延优先的配置，吞吐让位于尾延迟。</p>\n<p>取舍的工程判断可以落到一个简单规则：SLO 以首帧时间为主时，压批大小、提分块并行、精度偏保守；SLO 以总吞吐为主时，提批大小、压重叠比例、精度偏激进。两个配置不能同时最优，调度器必须显式选择。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-31\">三十一 · 流式输出与调度闭环：把拼接开销算进 SLO</h3>\n<p>流式输出要求解码池按帧批次持续产出，而不是等全部 latent 就绪后一次性解码。这带来一个调度约束：去噪池必须按块粒度产出 latent，块间重叠区的拼接在解码侧完成，拼接开销计入端到端延迟。设块数为 $N_{\\mathrm{blk}}$，每块解码耗时 $t_{\\mathrm{dec}}$，拼接耗时 $t_{\\mathrm{stitch}}$，则流式输出的首帧时间与总时间分别为：</p>\n<div class=\"formula\">$$T_{\\mathrm{first}}\\approx t_{\\mathrm{denoise}}(1)+t_{\\mathrm{dec}}(1),\\quad T_{\\mathrm{total}}\\approx N_{\\mathrm{blk}}\\cdot\\left(t_{\\mathrm{denoise}}+t_{\\mathrm{dec}}\\right)+N_{\\mathrm{blk}}\\cdot t_{\\mathrm{stitch}}$$</div>\n<p>拼接开销 $t_{\\mathrm{stitch}}$ 与重叠长度成正比，这正是第一部分 $\\rho$ 的延迟侧对价。调度闭环的做法是把 $t_{\\mathrm{stitch}}$ 作为解码池的已知成本纳入队列模型：解码池按“块 + 拼接”为一个服务单元排队，而不是按帧排队，避免拼接任务插队打乱流式节奏。具体例子：长视频流式输出时，若拼接任务与解码任务混排，用户看到的帧序会出现抖动；把拼接绑定到块解码之后作为固定尾随步骤，帧序稳定，代价是单块延迟略增。</p>\n<p>监控闭环需要覆盖三个信号：去噪池批利用率（反映 $\\eta$）、解码池队列深度（反映背压）、拼接耗时占比（反映 $\\rho$ 的延迟代价）。三者任一越界都触发调度参数调整：批利用率低则加大长度分桶，队列深则抑制去噪批大小，拼接占比高则压缩重叠长度。材料未给出具体阈值，工程上以相对变化率而非绝对值设阈值，避免硬件档位差异导致的误判。最后落在具体机制上：调度器不是静态配置，而是以这三个信号为输入的反馈环，视频扩散的时延—吞吐取舍在这个环里被持续重新求解。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-32\">三十二 · 分块重叠与批调度耦合时的边界条件</h3>\n<p>视频扩散的调度难点不在单请求，而在分块与重叠把请求切成了长度不一的块序列：每块都要走一遍时空注意力与 VAE 解码，重叠区被重复计算。连续批处理把不同请求的块拼进同一批，chunked prefill 再把长块拆成若干步填入，于是批内同时存在“首块预填”与“后续块解码”两种负载，二者的显存与带宽需求差异极大。此时的有效吞吐近似为 <span class=\"formula\">$$T_{\\text{eff}}=\\frac{\\sum_i B_i}{\\max(\\sum_i C_i,\\ \\sum_i M_i/BW)}$$</span>，其中 <span class=\"formula\">$$C_i$$</span> 为块计算量、<span class=\"formula\">$$M_i$$</span> 为块显存流量；分母取计算与带宽的较大者，说明分块重叠一旦把 <span class=\"formula\">$$M_i$$</span> 推高，调度就从算力受限滑向带宽受限，批大小再大也换不来吞吐。</p>\n<p>失效条件很具体：重叠长度增大时，重复计算与重复显存占用同步上升，而块间拼接的一致性收益并不随重叠线性增长；当重叠区占块长的比例高到使 <span class=\"formula\">$$M_i$$</span> 主导分母，连续批处理拼批反而放大带宽争用，尾延迟被最慢的那块拖住。优先级与抢占在此处代价高昂——被抢占的块已写入的 KV cache 与中间帧若不能保留，重算等于把重叠开销再付一次；若保留，显存又随并发线性上涨。因此抢占只适合在块边界发生，块内抢占基本等价于丢弃进度。</p>\n<p>分离式预填/解码在视频场景的边界同样清晰：预填侧承担时空注意力的大计算量，解码侧承担 VAE 还原像素帧的带宽压力，二者资源画像不同，分离可各自扩缩容；但块间重叠要求拼接时能看到相邻块的特征，跨节点传递中间张量的通信量随重叠区大小上升，NVLink 域内尚可，跨域则把带宽瓶颈从显存搬到链路。工程判断是：短块、低重叠、高并发走连续批处理加 chunked prefill；长视频、高重叠走分离式并只在块边界做优先级切换，同时用 NVFP4/FP8 压解码侧显存流量，把尾延迟的失控点从拼批挪回单块预算。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>适用边界</th><th>主要代价</th></tr></thead><tbody><tr><td>连续批处理 + chunked prefill</td><td>短块、低重叠、并发高</td><td>拼批放大带宽争用，尾延迟受最慢块支配</td></tr><tr><td>优先级与抢占</td><td>仅块边界可抢占</td><td>块内抢占丢弃进度，保留则显存随并发上涨</td></tr><tr><td>分离式预填/解码</td><td>长视频、高重叠</td><td>重叠区中间张量跨节点传输，瓶颈转向链路</td></tr></tbody></table>\n<h3 id=\"paper-video-diffusion-models-2022-sec-33\">三十三 · 从单卡放不下到切分：TP 切的是权重与激活，EP 切的是专家</h3>\n<p>视频扩散推理一旦越过单卡显存，第一件事不是“上多卡”，而是判断切什么。时空注意力的权重与激活在序列维度上同时膨胀，VAE 解码器的卷积权重在通道维度上膨胀，二者的切分逻辑不同。张量并行（TP）把单个线性层的权重矩阵按列或按行切开，每张卡只持有 <span>W</span> 的一个分片，前向时各卡算出部分和，再通过一次 All-Reduce 把部分和合并成完整激活。对时空注意力，TP 切的是 <span>Q/K/V</span> 投影与输出投影的通道维，注意力头被分散到不同卡上，每卡只算自己那几个头的 softmax，代价是每个注意力层后必须插入一次 All-Reduce。</p>\n<p>专家并行（EP）针对的是 DiT 中逐渐出现的 MoE 结构：每个 token 经门控网络选择若干专家，token 被路由到持有对应专家的卡上，算完再送回原卡。EP 的通信是 All-to-All，而不是 All-Reduce——每张卡既要发出自己路由出去的 token，又要接收别人路由进来的 token。All-to-All 的通信量与路由稀疏度、token 数成正比，且是双向不规则流量，对 NVLink 拓扑的对称性要求比 All-Reduce 更高。</p>\n<div class=\"formula\">$$\\text{TP 通信量} \\approx 2 \\cdot B \\cdot S \\cdot d \\cdot \\frac{N-1}{N},\\quad \\text{EP 通信量} \\approx 2 \\cdot B \\cdot S \\cdot d \\cdot k \\cdot \\frac{N-1}{N}$$</div>\n<p>其中 <span>B</span> 为批大小、<span>S</span> 为时空 token 数、<span>d</span> 为隐藏维、<span>k</span> 为每 token 激活专家数、<span>N</span> 为并行度。工程代价上，TP 的 All-Reduce 落在每个注意力层与每个 FFN 层之后，属于高频小消息；EP 的 All-to-All 落在每个 MoE 层，属于低频大消息但流量不规则。视频扩散的 token 数 <span>S</span> 随帧数与分辨率线性增长，TP 的通信量随 <span>S</span> 线性上升，这是长视频场景下 TP 度不能盲目加大的直接原因：TP 度越大，每层后的 All-Reduce 越频繁，而单层计算时间被切得越短，通信占比反而恶化。具体例子：把一段多帧视频的时空 token 摊到 8 卡做 TP=8，每卡每层只算 1/8 的通道，但每层后仍要一次全卡 All-Reduce，计算通信比随 TP 度下降，此时更优的选择往往是 TP=4 配合 PP 或 DP。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-34\">三十四 · PP 与 DP：流水线填的是气泡，数据并行填的是副本</h3>\n<p>流水线并行（PP）按层切分，把 DiT 的若干 transformer block 放到不同卡上，激活沿流水线逐段传递。PP 的核心代价是流水线气泡：在稳定状态下，气泡占比约为 <span>(P-1)/(M+P-1)</span>，<span>P</span> 为流水线级数、<span>M</span> 为微批数量。视频扩散的推理请求是自回归式的多步去噪，每一步都要走完整条链路，微批数量受显存与调度约束，因此 PP 的气泡在视频场景下比 LLM 解码更明显——LLM 解码可以把一个请求的多个 token 拼成微批，而扩散的一步去噪是一个整体，微批只能来自并发请求。</p>\n<p>数据并行（DP）则是每张卡持有完整权重、各自处理不同请求，卡间只在梯度同步时需要通信——推理阶段 DP 几乎不产生集合通信，代价落在权重副本的显存占用上。对视频扩散，DP 的显存代价是 <span>N</span> 份完整权重加 <span>N</span> 份各自请求的 KV cache 与激活，权重副本在 NVFP4/FP8 下被压缩，但激活与 KV cache 不会因 DP 而减少。工程判断：当单请求的激活与 KV cache 已经吃满显存时，DP 加卡不解决问题，必须回到 TP 或 PP 去切单请求本身。</p>\n<table class=\"mini\"><thead><tr><th>切分方式</th><th>切什么</th><th>集合通信</th><th>主要代价</th></tr></thead><tbody><tr><td>TP</td><td>权重与激活的通道维</td><td>每层 All-Reduce</td><td>高频小消息，计算通信比随度下降</td></tr><tr><td>EP</td><td>专家权重</td><td>每 MoE 层 All-to-All</td><td>不规则双向流量，依赖拓扑对称</td></tr><tr><td>PP</td><td>层</td><td>段间点对点激活传递</td><td>流水线气泡，受微批数量约束</td></tr><tr><td>DP</td><td>请求</td><td>推理阶段基本无</td><td>权重副本显存，不减少单请求激活</td></tr></tbody></table>\n<p>具体例子：一个长视频请求的时空注意力激活在单卡上放不下，若用 DP=8，每卡仍要放完整激活，问题原样存在；改用 PP=4 把 DiT 切成四段，单卡只放四分之一层的激活，但每步去噪要在四段间串行传递激活四次，端到端延迟随段数上升，且微批不足时气泡吃掉吞吐。这就是视频扩散并行拓扑的取舍核心：切分降低单卡显存，但引入的通信与气泡直接折算成延迟与吞吐。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-35\">三十五 · NVLink 5 与 NVSwitch：All-Reduce 走的是对称带宽，All-to-All 走的是对分带宽</h3>\n<p>Blackwell 世代的 GB200/GB300 NVL72 把 72 个 GPU 通过 NVLink 5 与 NVSwitch 连成一个域，卡间通信不再经过 PCIe 或 InfiniBand，而是走 NVSwitch 的交换结构。对 All-Reduce，NVSwitch 提供的是对称的全互联带宽，环形或树形算法都能在域内跑满；对 All-to-All，瓶颈落在对分带宽（bisection bandwidth）上——任意一半卡与另一半卡之间的总流量必须穿过交换结构的中截面，EP 的路由若恰好把流量压在中截面上，All-to-All 的实际有效带宽会低于标称值。</p>\n<p>工程上这意味着 EP 的专家放置不能只看负载均衡，还要看拓扑亲和：把高频互相路由的专家放在同一 NVSwitch 分区内，让跨分区流量最小化。TP 的 All-Reduce 则受益于 NVSwitch 的对称性，TP 度在域内可以放大，但前面已述，TP 度放大的代价是计算通信比恶化，NVSwitch 的高带宽并不能消除这个比例问题，只能把通信时间压短。公式上，单层 TP 的通信时间约为 <span>T_comm ≈ 通信量 / 有效带宽</span>，当有效带宽被 NVSwitch 抬到很高时，<span>T_comm</span> 变小，但 <span>T_comp</span> 随 TP 度线性变小，二者之比 <span>T_comm/T_comp</span> 反而随 TP 度上升——这是 NVLink 5 时代仍然要控制 TP 度的原因。</p>\n<p>推理系统代价：NVLink 5 与 NVSwitch 把域内集合通信的延迟压到微秒级，但视频扩散的每步去噪包含数十个注意力层与 FFN 层，每层一次 All-Reduce，累积的通信延迟在端到端延迟中不可忽略。具体例子：TP=8 的 DiT 在 NVL72 域内跑一步去噪，每层 All-Reduce 的延迟虽小，但层数乘以步数后，通信在端到端延迟中的占比会随 TP 度上升而上升；此时把 TP 降到 4、把剩余并行度给 DP，端到端延迟反而下降，因为 DP 不产生每层集合通信。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-36\">三十六 · NIXL 传输：分离式预填/解码与跨节点 KV cache 搬运</h3>\n<p>NIXL 是面向推理的传输层，负责在节点之间搬运 KV cache 与激活，典型场景是分离式预填/解码：预填节点算完时空注意力的 KV，把 KV cache 通过 NIXL 传给解码节点，解码节点只做后续去噪步。视频扩散的 KV cache 体量随帧数与分辨率增长，跨节点搬运的代价落在网络带宽上，而不是 NVLink 域内带宽——一旦跨出 NVL72 域，传输走的是 InfiniBand 或以太网，带宽低一个档位，KV cache 搬运时间可能超过解码计算时间。</p>\n<p>工程判断：分离式预填/解码对视频扩散的收益取决于 KV cache 体量与跨域带宽之比。若 KV cache 体量大到搬运时间超过预填与解码的串行时间，分离式部署反而增加端到端延迟；此时应把预填与解码放在同一 NVL72 域内，用 NVLink 5 搬运，或干脆不分离。NIXL 的价值在于把搬运抽象成可编排的传输原语，让调度器能按 KV cache 体量与链路带宽选择搬运路径，而不是硬编码一条路径。具体例子：长视频分块推理时，每块的 KV cache 需要在块间拼接阶段被复用，NIXL 可以把上一块的 KV cache 从计算节点搬到拼接节点，搬运量随分块重叠长度上升——重叠越长，复用越多，但搬运量也越大，这是分块策略与传输策略的联合取舍。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-37\">三十七 · 通信什么时候成为瓶颈：三个可判定的条件</h3>\n<p>通信成为瓶颈不是靠感觉判断，而是靠三个可判定的条件。第一，计算通信比：单层计算时间 <span>T_comp</span> 与单层通信时间 <span>T_comm</span> 之比小于某个阈值时，通信开始主导。视频扩散的 <span>T_comp</span> 随 token 数增长，但 TP 切分把 <span>T_comp</span> 按度缩小，<span>T_comm</span> 却不随度缩小（All-Reduce 的通信量与 TP 度弱相关），因此 TP 度越高越容易触发这个条件。</p>\n<div class=\"formula\">$$\\text{效率} = \\frac{T_{\\text{comp}}}{T_{\\text{comp}} + T_{\\text{comm}}},\\quad \\text{瓶颈条件：} T_{\\text{comm}} &gt; \\alpha \\cdot T_{\\text{comp}}$$</div>\n<p>第二，气泡占比：PP 的气泡占比 <span>(P-1)/(M+P-1)</span> 超过可接受阈值时，PP 的吞吐收益被气泡吃掉。视频扩散的微批数量受并发请求数与显存约束，并发不足时气泡占比高，PP 不划算。第三，跨域搬运比：KV cache 搬运时间与解码计算时间之比超过阈值时，分离式部署不划算。这三个条件都落在具体机制上，而不是笼统的“通信有开销”。</p>\n<p>推理系统代价：通信瓶颈的代价最终折算成延迟、吞吐、显存与功耗四项。延迟上，每层 All-Reduce 与每 MoE 层 All-to-All 累积；吞吐上，气泡与通信等待让卡在等数据；显存上，TP 与 PP 切分降低单卡显存但增加通信缓冲；功耗上，NVSwitch 与网络接口在满带宽搬运时功耗上升，长视频高并发场景下这部分功耗不可忽略。具体例子：一个 EP 度较高的 MoE DiT 在 NVL72 域内跑 All-to-All，若专家放置不当导致跨分区流量集中在中截面，有效带宽下降，单层 All-to-All 时间上升，端到端延迟随之上升；把专家按路由亲和重排后，跨分区流量下降，同一硬件配置下延迟回落——这说明通信瓶颈往往不是带宽不够，而是拓扑与放置不匹配。</p>\n<p>监控上，需要覆盖每层集合通信的耗时、NVSwitch 端口的吞吐、NIXL 搬运的字节数与链路利用率，以及 PP 各段之间的等待时间。失败模式包括显存溢出与带宽瓶颈两类：显存溢出由切分不足或 KV cache 膨胀触发，带宽瓶颈由 TP 度过高、EP 放置不当或跨域搬运过多触发。二者在监控上的表现不同，前者是 OOM，后者是集合通信耗时占比上升而计算单元利用率下降。工程判断落在具体机制上：先测单层计算通信比，再决定 TP 度；先测气泡占比，再决定 PP 级数；先测 KV cache 搬运比，再决定是否分离式部署——这三个比值是并行拓扑选择的直接依据，而不是架构参数的堆砌。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-38\">三十八 · 并行切分在视频扩散里的失效边界</h3>\n<p>视频扩散的并行切分不是把 LLM 那套 TP/EP/PP/DP 直接搬过来就完事。时空注意力的 Q/K/V 沿帧序列展开，序列长度随分块与重叠策略膨胀，TP 切分注意力头时每层都要一次 All-Reduce 把部分结果拼回；而 VAE 解码器是卷积主导、几乎无张量并行收益，切多了只会让每张卡等通信。真正决定拓扑的是“哪一段在等带宽”：注意力段吃 All-Reduce 的时延，解码段吃显存带宽与激活搬运，分块拼接段吃跨卡 All-to-All 的块间重叠交换。工程判断应落在“把通信密集段压在 NVLink 域内、把解码段尽量留在单卡或单节点”，而不是追求全局切分对称。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(T_{\\text{attn}}^{\\text{comp}} + \\frac{S}{B_{\\text{NVLink}}}\\cdot\\log P,\\; T_{\\text{vae}}^{\\text{mem}}\\right)$$</div>\n<p>上式给出一个可操作的边界：当注意力计算时间被通信项压过，加卡就是负收益。$S$ 是每步需规约的激活字节，$B_{\\text{NVLink}}$ 是链路有效带宽，$P$ 是参与规约的 rank 数；$\\log P$ 来自环形或树形 All-Reduce 的跳数。视频场景里 $S$ 随帧数与 token 数线性涨，重叠区域又让有效 token 变多，于是同一套 TP 度在短视频上跑得动、在长视频分块上就翻车——这是分块策略与并行拓扑耦合的典型失效点。跨节点时 All-Reduce 落到 InfiniBand，跳数与带宽都劣化，此时应改用 PP 把层切开、只在边界传激活，或用 NIXL 做点对点的 KV/激活搬运，把集合通信换成可重叠的传输。</p>\n<table class=\"mini\"><thead><tr><th>切分</th><th>视频扩散中的适用段</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>TP</td><td>时空注意力头、线性投影</td><td>每层 All-Reduce，时延随 P 增</td><td>序列长、重叠多，通信压过计算</td></tr><tr><td>PP</td><td>注意力块与 VAE 解码分段</td><td>流水气泡、边界激活搬运</td><td>批小、流式输出节奏不齐</td></tr><tr><td>EP/All-to-All</td><td>分块重叠区的块间交换</td><td>不规则流量、尾延迟</td><td>块大小不均、重叠比例高</td></tr><tr><td>DP</td><td>并发请求副本</td><td>KV cache 显存翻倍</td><td>显存先于带宽成为瓶颈</td></tr></tbody></table>\n<p>具体到一次长视频请求：帧序列切块后，重叠区需要在相邻块间做一致性拼接，若两块落在不同 rank，就要一次 All-to-All 交换重叠 token 的中间表示；这笔流量与重叠长度成正比，而重叠长度本身是为拼接质量付的费。批量与流式输出阶段，KV cache 随并发上升，DP 复制能把吞吐拉起来却先把显存吃满，此时瓶颈从 NVLink 带宽切换到 HBM 容量，监控必须同时看显存占用与集合通信等待时间，单看吞吐会误判。NVFP4/FP8 精度在这里的作用是压缩 $S$ 与 KV 占用，让通信项和显存项同时下降，但它改变的是数值稳定性边界，解码质量需在精度切换阈值上单独验证，材料未给出该阈值，工程上只能以显存溢出与带宽瓶颈两类失败模式做兜底监控。</p>\n<h3 id=\"paper-video-diffusion-models-2022-sec-39\">三十九 · 精度塌陷的触发链：从权重到像素的逐级放大</h3>\n<p>视频扩散推理的精度塌陷不是单点故障，而是一条沿链路逐级放大的触发链。NVFP4/FP8 的选择在算子层引入量化误差，误差经时空注意力沿帧序列与 token 维度累积，再经 VAE 解码器从隐空间映射回像素域时被非线性激活放大，最终表现为帧间闪烁、块边界色带或整体过饱和。诊断的关键是把“看起来糊”拆成可定位的三段：算子输出分布偏移、隐空间数值越界、解码器重建失真。工程上应在这三段各埋一个探针，而不是只在端到端出图后凭肉眼判断。</p>\n<p>量化误差的传播可用一阶近似刻画。设某层输入为 <span>\\(x\\)</span>，量化算子为 <span>\\(Q(\\cdot)\\)</span>，则扰动 <span>\\(\\delta = Q(x)-x\\)</span> 经后续层雅可比 <span>\\(J\\)</span> 放大为 <span>\\(J\\delta\\)</span>；沿 <span>\\(L\\)</span> 层累积的误差上界近似为：</p>\n<div class=\"formula\">$$\\|\\delta_{\\text{out}}\\| \\lesssim \\left(\\prod_{l=1}^{L}\\|J_l\\|\\right)\\|\\delta_0\\| + \\sum_{l=1}^{L}\\left(\\prod_{k&gt;l}\\|J_k\\|\\right)\\|\\delta_l\\|$$</div>\n<p>这条式子给出的工程判断是：误差放大取决于雅可比谱范数的连乘，而时空注意力在长序列上恰恰容易让该连乘变大。因此精度塌陷往往不是均匀发生，而是在帧数增长、注意力窗口拉长后突然出现——这与“短片段正常、长视频崩坏”的现场表现一致。定位手段是分层记录激活的均值与方差漂移，找出雅可比范数异常的那一层，而不是盲目全局回退到更高精度。</p>\n<p>具体例子：长视频分块推理时，重叠区域在两块之间被重复计算与拼接。若两块使用了不同的量化舍入路径，重叠区的像素在拼接缝上会出现可观测的色阶跳变。此时端到端指标可能仍“及格”，但拼接缝是精度塌陷的早期信号。代价上，全局回退到 FP8 以上精度会直接抬高显存占用与带宽需求，因为权重与激活的位宽上升使每步搬运字节数增加，端到端延迟随之上升；而定点修复单层则只影响该层的吞吐。监控应把“重叠区一致性”作为独立指标，而不是混在整体画质里。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-40\">四十 · OOM 的三条来路：激活峰值、KV cache 与解码缓冲</h3>\n<p>视频扩散推理的 OOM 有三条彼此独立的来路，混为一谈会导致回滚策略失准。第一条是时空注意力的激活峰值：注意力矩阵规模随帧数与 token 数增长，显存占用满足 <span>\\(\\mathrm{Mem}\\propto N_{\\mathrm{frame}}\\cdot N_{\\mathrm{token}}\\cdot d\\)</span>，长序列下这一项会瞬间吃掉大量显存。第二条是批量与流式输出阶段的 KV cache：并发上升时缓存随请求累积，调度策略决定其增长斜率。第三条是 VAE 解码器的中间缓冲：解码器还原像素帧时需要保持较大特征图，分块解码可削减峰值但引入拼接开销。</p>\n<p>诊断 OOM 的第一步是区分“瞬时峰值”与“稳态占用”。瞬时峰值多来自注意力算子的单次大分配，稳态占用多来自 KV cache 与解码缓冲的累积。工程做法是在分配器层打点，记录每次大分配的调用栈与时刻，把 OOM 现场还原为“哪一类分配在何时触顶”。若峰值出现在注意力前向，优先考虑分块或序列切分；若稳态随并发线性上升，优先考虑 KV cache 淘汰与批大小上限；若峰值出现在解码阶段，优先考虑解码分块与重叠比例调整。</p>\n<p>具体例子：长视频请求按分块与重叠策略切分后，若重叠长度设置过大，块间重复计算使激活峰值叠加，OOM 发生在拼接前的最后一块。此时把重叠长度缩短可降低峰值，但拼接一致性变差，需要与画质指标联动评估。代价上，缩短重叠减少显存与计算，却把风险转移到块边界；增大重叠提升一致性，却抬高显存峰值与端到端延迟。监控应同时记录“峰值显存/请求”与“块边界一致性”，让两个指标共同决定重叠参数，而不是单看 OOM 是否消失。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-41\">四十一 · 批抖动与尾延迟：调度器看不见的成本</h3>\n<p>批抖动指同一负载下批大小与请求完成时间出现非预期波动，尾延迟指长尾请求的完成时间显著偏离中位数。视频扩散推理中，这两者同源：请求的视频长度分布不均，分块与重叠策略使单请求的计算量差异被放大，而批量调度又按固定窗口聚合，导致短请求被长请求拖住。调度器若只按请求数而非按 token 量或分块数计量，就会出现“批看起来很满、尾延迟却失控”的现象。</p>\n<p>定位批抖动需要把批的构成拆开看。设批内请求的计算量为 <span>\\(c_i\\)</span>，批完成时间近似由最大者决定：</p>\n<div class=\"formula\">$$T_{\\text{batch}} \\approx \\max_{i\\in\\text{batch}} c_i + T_{\\text{overhead}},\\quad \\text{jitter}\\propto \\mathrm{Var}(c_i)$$</div>\n<p>这条式子说明：批内计算量方差越大，批完成时间越被最重请求支配，尾延迟越难压。工程手段是按分块数或 token 量做长度感知的批聚合，把重请求单独成批或限制其与轻请求混批的比例。代价是批利用率下降：重请求单独成批时 GPU 占用率降低，吞吐下降；但尾延迟收敛，SLO 更稳。监控应记录批内计算量的分布而非仅记录平均批大小，否则抖动会被平均值掩盖。</p>\n<p>具体例子：流式输出场景下，一个长视频请求与若干短请求混批，长请求的分块解码持续占用 KV cache 与解码缓冲，短请求已完成却无法释放批资源，尾延迟被拉长。把长请求移出混批、改为独立流式通道后，短请求的尾延迟收敛，代价是长请求的吞吐略降。这里的工程判断是：尾延迟敏感的场景应牺牲部分批利用率换取可预测性，而不是追求峰值吞吐。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-42\">四十二 · 静默降级：指标及格但语义已坏</h3>\n<p>静默降级是最难诊断的失败模式：端到端延迟与吞吐指标正常，显存未触顶，但生成结果的语义一致性已经损坏。视频扩散中，静默降级常表现为运动连续性断裂、物体身份在帧间漂移、或长视频后段与首帧失去关联。其根源多在分块与重叠的拼接逻辑、KV cache 淘汰策略、或精度切换的边界条件——这些环节不抛异常，只悄悄改变数值路径。</p>\n<p>诊断静默降级需要语义级探针，而非系统级指标。可行做法是在固定随机种子下对同一请求做“金标准重放”：用高精度、无分块、无淘汰的路径生成参考输出，再与生产路径逐帧比对隐空间特征的距离。设参考隐特征为 <span>\\(z^{\\star}_t\\)</span>，生产路径为 <span>\\(z_t\\)</span>，则漂移度量为：</p>\n<div class=\"formula\">$$D=\\frac{1}{T}\\sum_{t=1}^{T}\\left\\|z_t-z^{\\star}_t\\right\\|_2,\\quad \\text{alert if } D \\text{ exceeds a calibrated bound}$$</div>\n<p>该度量对拼接缝、淘汰边界与精度切换点敏感，能在画质肉眼可见崩坏之前给出告警。代价是金标准重放需要额外算力与显存，不能对每个请求执行，只能按采样率抽检。工程判断是把抽检频率与请求重要性挂钩：高价值长视频请求提高抽检率，普通短请求降低抽检率，用采样成本换取静默降级的可观测性。</p>\n<p>具体例子：KV cache 淘汰策略在并发上升时开始丢弃较早帧的缓存，系统指标一切正常，但长视频后段的运动与前段脱节。逐帧隐特征比对显示漂移在后段单调上升，定位到淘汰阈值设置过激。回滚方式是放宽淘汰阈值或改为按帧重要性保留，代价是显存占用上升、可承载并发下降。监控应把漂移度量与并发水平联合观察，找出“并发超过某水平后漂移开始上升”的拐点。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-43\">四十三 · 监控分层与回滚闸门</h3>\n<p>监控应分三层部署，避免用一套指标包打天下。第一层是资源层：显存峰值、带宽利用率、KV cache 占用随并发的斜率，用于捕捉 OOM 与带宽瓶颈。第二层是调度层：批内计算量方差、尾延迟分位数、批利用率，用于捕捉批抖动。第三层是语义层：重叠区一致性、隐特征漂移、解码重建误差，用于捕捉精度塌陷与静默降级。三层指标各自独立告警，避免资源层正常掩盖语义层崩坏。</p>\n<p>回滚闸门应按失败模式分级，而不是一刀切重启。精度塌陷的回滚单位是“层或算子”，把异常层切回更高精度，其余保持原精度，代价局部化；OOM 的回滚单位是“参数”，先缩重叠长度或降批大小上限，再考虑解码分块；批抖动的回滚单位是“调度策略”，把长度感知聚合切回保守的固定窗口；静默降级的回滚单位是“缓存与拼接逻辑”，放宽淘汰阈值或关闭激进拼接。每一级回滚都应附带代价记录：显存变化、延迟变化、吞吐变化，供后续容量规划参考。</p>\n<p>具体例子：一次并发爬升触发了 KV cache 淘汰过激，语义层漂移告警先于资源层告警出现。闸门按分级策略只回滚淘汰阈值，不动精度与分块参数，系统在显存略升的情况下恢复语义一致性，吞吐损失被限制在单一维度。这种“最小回滚面”的做法依赖三层监控的独立性：若只有资源层监控，此次降级会被完全漏掉，直到用户侧投诉才被发现。工程判断是：监控分层的价值不在指标数量，而在失败模式与回滚单位的一一对应。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-44\">四十四 · 诊断顺序：先定类，再定量，后定回滚</h3>\n<p>面对一次现场故障，诊断顺序应是“先定类、再定量、后定回滚”。定类指判断故障属于精度塌陷、OOM、批抖动、尾延迟还是静默降级——这决定看哪一层监控。定量指在定类之后测量具体幅度：漂移度量的斜率、显存峰值的来源、批内方差的分布、尾延迟的分位数。定回滚指按失败模式选择最小回滚面，并记录代价。跳过定类直接调参，往往把 OOM 误判为精度问题而盲目升精度，反而加剧显存压力。</p>\n<p>定类的可操作判据是：资源层告警且伴随分配失败，归为 OOM；资源层正常但调度层尾延迟分位数恶化，归为批抖动或尾延迟；资源层与调度层均正常但语义层漂移上升，归为静默降级；语义层出现拼接缝或色带且与精度切换时间相关，归为精度塌陷。四类判据互斥，避免同一现象被多个团队重复归因。代价上，定类本身需要监控数据留存与调用栈记录，这部分存储与采样开销应计入容量规划，而不是当作免费的可观测性。</p>\n<p>具体例子：长视频请求在并发爬升后出现后段画质崩坏，资源层显存未触顶、调度层尾延迟正常，语义层漂移在后段单调上升。按判据归为静默降级，定量显示漂移拐点与 KV cache 淘汰阈值相关，回滚只放宽淘汰阈值并记录显存上升幅度。整个诊断不触碰精度与分块参数，回滚面最小。这里的工程判断落在具体机制上：失败模式的分类精度决定了回滚代价，而分类精度又取决于监控分层是否与失败模式一一对应——这是视频扩散推理部署中比单点调参更值得投入的工程能力。</p>\n<h3 id=\"paper-video-diffusion-models-2022-sec-45\">四十五 · 基准口径的三层解耦：模型、硬件、负载</h3>\n<p>视频扩散推理的基准之所以难读，根源在于三个维度被混在同一张表里：模型侧（时空注意力结构、VAE 解码器、分块策略）、硬件侧（B200/B300 的 SM100/SM103 档位、GB200/GB300 NVL72 的机柜形态）、负载侧（分辨率、帧数、batch、并发、流式与否）。任何一组吞吐或延迟数字，只有在这三层同时钉死时才可比。材料对这三层均未给出具体数值，因此本部分的任务不是复述数字，而是给出一个可复用的口径框架，让读者拿到任意一份视频扩散推理报告时能判断“这个提升能不能信”。</p>\n<p>口径框架的第一条规则：把端到端延迟拆成可归因的段。一次请求的时间轴至少包含时空 token 化、时空注意力主干（含 N 步去噪迭代）、VAE 解码、分块拼接、流式输出五段。设单步去噪耗时 <span>t<sub>step</sub></span>、去噪步数 <span>N</span>、VAE 解码耗时 <span>t<sub>vae</sub></span>、分块数与重叠引入的额外计算系数 <span>ρ</span>（<span>ρ≥1</span>），则端到端延迟的粗粒度模型为：</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}} \\approx \\rho \\cdot N \\cdot t_{\\mathrm{step}} + t_{\\mathrm{vae}} + t_{\\mathrm{post}}$$</div>\n<p>这个式子的工程价值在于它直接告诉你哪些加速手段改变的是哪一项。<span>N</span> 的缩减（步数蒸馏类工作）只作用于第一项；<span>ρ</span> 的优化（分块与重叠策略）只作用于第一项且与显存收益对冲；<span>t<sub>vae</sub></span> 的优化（解码器并行化、精度选择）独立成项，不能被“注意力加速”的收益掩盖。若一份报告只报总吞吐提升而不拆项，就无法判断提升来自 <span>N</span>、<span>ρ</span> 还是 <span>t<sub>vae</sub></span>——这正是不可比的主要来源。</p>\n<p>代价落点：<span>t<sub>vae</sub></span> 在长视频场景下往往不是常数，它随帧数与分辨率线性甚至超线性增长，且受显存带宽约束而非算力约束；把 VAE 解码放在与注意力同一张卡上串行执行，会让端到端延迟出现“注意力很快、解码拖尾”的形态。具体例子：同一份报告声称“注意力算子提速若干倍”，但端到端只改善很小，此时应优先怀疑 <span>t<sub>vae</sub></span> 与 <span>t<sub>post</sub></span> 未被并行化，而不是怀疑注意力优化无效。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-46\">四十六 · 硬件档位与并行拓扑：为什么跨档位数字不可比</h3>\n<p>Blackwell 的推理基准必须标注档位，因为 SM100/SM103 的单卡算力、HBM 容量与带宽、以及 tcgen05/TMEM 的可用性决定了同一算子的实现形态。B200 与 B300 属单机档位，GB200/GB300 NVL72 属机柜档位，后者通过 NVLink 5 把大量 GPU 连成域，允许把时空注意力的序列维切分到跨卡。材料未给出任何具体档位数字，因此这里只给判断规则：跨档位比较吞吐是无效的，因为机柜档位的聚合带宽与单卡档位的显存容量不在同一量级，而视频扩散的瓶颈恰恰在显存与带宽上。</p>\n<p>并行拓扑对基准的影响可以用一个简单的切分代价模型表达。设序列维切分度为 <span>S</span>，每层注意力需要一次全序列归约（all-gather 或 ring），单次通信量为 <span>M</span> 字节，链路有效带宽为 <span>B</span>，则每步每层的通信代价为：</p>\n<div class=\"formula\">$$t_{\\mathrm{comm}} \\approx \\frac{M \\cdot (S-1)}{S \\cdot B}$$</div>\n<p>当 <span>S</span> 增大，单卡计算量下降但通信项上升，存在一个由 <span>B</span> 决定的拐点。NVLink 5 的域内带宽使机柜档位的拐点显著右移，这意味着“在 NVL72 上序列并行到较大切分度仍然划算”这一结论不能搬到单机档位。反过来，单机档位上把切分度调大，基准会呈现“算力利用率高但端到端不降”的形态。</p>\n<p>代价落点：并行拓扑还改变 KV cache 的分布形态。序列并行下 KV cache 按序列维切分，单卡显存占用下降但跨卡访问增加；张量并行下 KV cache 按头维切分，单卡占用下降但每步都要做注意力输出的归约。两种切分对 TTFT 与 TPOT 的影响方向不同——前者主要压 TPOT 的通信项，后者同时压 TTFT 的预填并行度。具体例子：一份报告在机柜档位上报告了良好的 TPOT，读者若把它当作单卡档位的预期，会在预填阶段遭遇显存溢出，因为单卡档位没有足够的 HBM 容纳未切分的 KV cache。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-47\">四十七 · batch、并发与流式：三个被混用的量</h3>\n<p>视频扩散推理报告里最常见的口径错误是把 batch、并发请求数与流式输出混为一谈。batch 是单次前向里打包的样本数，直接改变算子的算术强度；并发是调度器同时持有的请求数，直接改变 KV cache 与中间激活的显存占用；流式输出决定结果是否按帧或按块增量返回，改变的是 TTFT 的定义而非计算量。三者对指标的作用方向不同，必须分开报。</p>\n<p>以显存占用为例，设单请求的 KV cache 与中间激活占用为 <span>m</span>，并发数为 <span>C</span>，显存预算为 <span>M<sub>budget</sub></span>，则可行的并发上限近似为：</p>\n<div class=\"formula\">$$C_{\\max} \\approx \\left\\lfloor \\frac{M_{\\mathrm{budget}} - M_{\\mathrm{model}} - M_{\\mathrm{workspace}}}{m} \\right\\rfloor$$</div>\n<p>这个式子的含义是：并发不是可以无限调高的旋钮，它被 <span>m</span> 与工作区显存硬约束。视频扩散的 <span>m</span> 随帧数与分辨率增长，因此长视频场景下 <span>C<sub>max</sub></span> 会显著低于图像扩散。若一份报告只报“吞吐随并发上升”，却不报 <span>C<sub>max</sub></span> 与到达 <span>C<sub>max</sub></span> 后的排队行为，那么它的吞吐曲线在高并发段是不可信的——那一段的“吞吐”很可能只是排队延迟被排除在统计之外的结果。</p>\n<p>代价落点：流式输出把 TTFT 的定义从“首帧像素可用”变成“首个可交付单元可用”。在分块与重叠策略下，首块必须等重叠区域计算完成才能拼接，因此流式 TTFT 受重叠长度直接拖累。具体例子：同一模型在非流式口径下报出较低的 TTFT，切到流式口径后 TTFT 上升，这不是实现退步，而是口径变了——两份报告若一流式一非流式，其 TTFT 不可直接比较。TPOT 在视频场景下应定义为相邻可交付单元之间的间隔，而非相邻 token 间隔，否则会把分块拼接的开销摊薄到看不见。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-48\">四十八 · 指标定义与不可比清单</h3>\n<p>把指标定义钉死是读数字的前提。下表给出本领域四个核心指标在视频扩散语境下的定义与常见污染源，读者可用它快速筛查一份报告的口径是否自洽。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>定义（视频扩散口径）</th><th>常见污染源</th></tr></thead><tbody><tr><td>TTFT</td><td>请求进入到首个可交付单元（首帧或首块）可用的时间</td><td>流式与非流式混报；重叠区域计算被排除在计时外</td></tr><tr><td>TPOT</td><td>相邻可交付单元之间的平均间隔</td><td>用 token 间隔替代帧/块间隔；拼接开销未计入</td></tr><tr><td>吞吐</td><td>单位时间内完成的请求数或产出的帧数</td><td>高并发段排队延迟被排除；batch 与并发混用</td></tr><tr><td>显存</td><td>峰值显存占用，含模型、KV cache、工作区、分块缓冲</td><td>只报模型权重；分块缓冲与重叠副本未计入</td></tr></tbody></table>\n<p>不可比清单可以归纳为五类。第一类，跨硬件档位：单机档位与机柜档位的聚合带宽不同，吞吐不可比。第二类，跨精度：NVFP4 与 FP8 在显存占用与解码质量上不同，材料未给出精度切换阈值，因此任何“同精度下”的声明都必须显式标注精度模式，否则不可比。第三类，跨分块策略：分块大小与重叠长度改变 <span>ρ</span> 与显存占用，两份报告若分块参数不同，其端到端延迟不可比。第四类，跨 batch/并发口径：如上节所述。第五类，跨步数：<span>N</span> 不同的两份报告，其单步耗时可比而端到端不可比。</p>\n<p>代价落点：显存指标的污染最隐蔽。分块与重叠策略需要为重叠区域保留额外缓冲，这部分显存在报告峰值时经常被漏计；而它恰恰是长视频场景下触发显存溢出的直接原因。具体例子：一份报告声称“显存占用低于某阈值”，但该阈值只覆盖了模型权重与单块工作区，未覆盖重叠副本与拼接缓冲，读者按此配置部署会在长视频请求上遇到显存溢出——这正是失败模式中显存溢出与带宽瓶颈并列的机制根源。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-49\">四十九 · 数字怎么读：从机制反推可信度</h3>\n<p>读一份视频扩散推理报告，正确的顺序是先看机制再看数字。第一步，确认报告是否拆分了 <span>N·t<sub>step</sub></span>、<span>t<sub>vae</sub></span>、<span>t<sub>post</sub></span> 三段；未拆分的总延迟提升无法归因。第二步，确认硬件档位与并行拓扑是否标注；未标注的吞吐数字只能当作定性参考。第三步，确认精度模式与分块参数是否标注；这两者直接改变 <span>ρ</span> 与显存占用。第四步，确认 batch、并发、流式三个量是否分开报；混报的吞吐曲线在高并发段不可信。</p>\n<p>一个可操作的判据：若报告的加速比显著大于其机制所能解释的上界，则应怀疑口径。例如，仅优化注意力算子实现（不改变 <span>N</span>、<span>ρ</span>、<span>t<sub>vae</sub></span>）所能带来的端到端加速上界，由注意力在端到端延迟中的占比决定；若报告声称的加速比超过该占比的倒数，则必然有某项被排除在计时之外。这个判据不需要具体数字，只需要机制层面的占比估计，因此适用于材料未给出数值的情形。</p>\n<p>代价落点：功耗维度在材料中未给出任何数字，但它在机柜档位上是容量规划的真实约束。NVL72 形态下整柜功耗决定了可长期维持的并发上限，而视频扩散的长尾请求会拉高平均功耗。因此任何在机柜档位上报告“持续吞吐”的报告，若不标注功耗约束下的降频行为，其吞吐数字在长时间运行下不可复现。具体例子：短时基准跑出的吞吐在持续负载下因功耗墙而降频，两份报告一份短时一份长时，其吞吐不可比——这属于跨负载时长口径的不可比，应加入上节清单。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-50\">五十 · 工程判断：把基准写成可复现的口径卡</h3>\n<p>对工程团队而言，最有用的做法不是追求一个绝对数字，而是为每次基准产出一张口径卡：固定模型结构（时空注意力配置、VAE 解码器版本）、固定硬件档位与并行拓扑、固定精度模式（NVFP4 或 FP8 及其切换条件）、固定分块大小与重叠长度、固定 batch 与并发上限 <span>C<sub>max</sub></span>、固定流式与否，并分别报 TTFT、TPOT、吞吐、峰值显存四组量。任何跨卡片的比较，只允许在除被测变量外其余字段完全一致的条件下进行。</p>\n<p>这张口径卡的价值在于它把“提升”变成可归因的量。当被测变量是精度模式时，卡片同时暴露显存占用的变化与解码质量的定性差异；当被测变量是分块重叠长度时，卡片同时暴露 <span>ρ</span> 带来的额外计算与拼接缓冲的显存增量；当被测变量是并行切分度 <span>S</span> 时，卡片通过 <span>t<sub>comm</sub></span> 项暴露通信拐点。三者都不能只报“更快”，因为每一项都有明确的对冲代价。</p>\n<p>最后落到一个具体机制判断：在材料未给出任何吞吐、延迟与显存数值的前提下，本领域唯一可靠的基准结论是机制层面的——时空注意力与 VAE 解码构成计算主干且受显存与带宽约束，分块与重叠以额外计算换显存，批量与流式受 KV cache 与调度约束，NVFP4/FP8 在解码质量与显存占用间权衡。任何超出这四条的定量声明，都必须附带上述口径卡的完整字段，否则应被视为不可比。工程上应把这条规则写进基准脚本的元数据校验里：字段缺失即拒绝入库，从流程上杜绝跨口径数字的混用。</p>\n<h3 id=\"paper-video-diffusion-models-2022-sec-51\">五十一 · 迁移的第一道关：注意力形态决定搬运成本</h3>\n<p>把本方案搬到别的模型上，第一个要判断的不是框架 API 兼容性，而是目标模型的注意力是不是仍然是“全时空稠密”的。论文的推理链路把时空注意力当作计算主干，其代价结构由 <span class=\"formula\">$$\\mathrm{Attn}(Q,K,V)=\\mathrm{softmax}\\left(\\frac{QK^{\\top}}{\\sqrt{d}}\\right)V,\\quad \\mathrm{Mem}\\propto N_{\\mathrm{frame}}\\cdot N_{\\mathrm{token}}\\cdot d$$</span> 直接决定：显存随帧数与 token 数线性增长，而注意力矩阵本身随序列长度平方增长。迁移到纯图像扩散模型时，帧维退化为 1，分块与重叠策略整体失效——重叠区本来是为块间时间一致性服务的，图像上没有对应语义，硬套只会白付拼接算力。迁移到以状态空间或线性注意力为主干的生成模型时，softmax 注意力被替换，KV cache 的增长曲线从线性变为常数或近线性，此时本方案里“按并发预留 KV 显存”的调度逻辑需要重写，而不是调参。工程判断：先看目标模型的时间轴是否真的参与注意力，再看 KV 增长是线性还是常数；两者任一不成立，本方案的显存预算模型就得推翻重来，而不是微调。</p>\n<p>具体例子：把一个短视频请求的帧序列切成时空 token 后送入注意力算子，若目标模型改成了逐帧独立去噪再拼接，那么块间重叠带来的额外计算就变成纯开销，端到端延迟不降反升。这类迁移失败的根因不在精度，而在计算图结构不匹配。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-52\">五十二 · VAE 解码器：迁移时最容易被低估的一段</h3>\n<p>论文明确把 VAE 解码器还原像素帧列为受显存与带宽约束的环节，且是端到端延迟的重要组成。迁移到别的领域时，解码器的输出形态变化会直接改变这段的代价：视频是三维张量，解码输出带宽压力集中在帧缓冲的写回；若迁到音频或长序列文本类生成，解码器输出的时间轴语义不同，分块边界与重叠比例必须重新标定。更关键的是精度迁移：材料只说明 NVFP4/FP8 的选择影响解码质量与显存占用，未给出切换阈值。工程上这意味着迁移时不能照搬原方案的精度档位，而要在目标模型的解码器上单独做数值稳定性走查——扩散主干用低精度、解码器保持较高精度是一种常见折中，但材料未给出该策略的具体数字，只能作为机制性判断而非结论。</p>\n<p>代价判断：解码阶段的显存峰值往往出现在一次性还原整段视频时，若目标领域输出更长，必须沿用分块解码而非整段解码，否则显存溢出会成为首要失败模式。这与前文“失败模式与诊断”里讲的显存溢出是同一类问题，但迁移场景下触发点从注意力转移到了解码器。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-53\">五十三 · 分块与重叠：收益边界在哪里</h3>\n<p>长视频分块与重叠是本方案处理显存约束的核心手段，重叠区用于块间拼接与一致性保持，代价是额外计算与显存开销。迁移判断的关键是“重叠比例是否随目标领域的时间相关性变化”。视频帧间相关性随帧率与场景变化，重叠长度需要覆盖足以维持一致性的时间窗；迁到相关性更弱或更强的序列生成任务时，同一重叠比例要么浪费算力，要么拼接处出现可见断裂。材料未给出具体分块大小与重叠长度，因此迁移时只能按机制推导：重叠开销近似正比于重叠帧数占总帧数的比例，块数越多，拼接次数与中间缓冲越多，显存峰值出现在同时持有相邻块输出的时刻。</p>\n<p>具体例子：一个长视频请求被切成若干块，每块独立去噪后按重叠区做加权拼接；若目标模型改为自回归逐块生成，块间不再需要重叠缓冲，但引入了跨块的状态传递，KV cache 的驻留策略要重写。这说明分块策略不是可移植的常量，而是与生成范式绑定的设计。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-54\">五十四 · 批量与流式：调度假设的移植性</h3>\n<p>批量与流式输出阶段，KV cache 与显存占用随并发上升，调度策略影响吞吐与延迟。迁到别的服务形态时，最先崩的是这个假设：本方案默认请求是“一次视频生成”，有明确的起止；若目标场景是持续流式输出（例如边生成边推流），请求边界模糊，连续批处理的组批窗口与 KV 回收时机都要重新设计。材料未给出并发与 SLO 数字，因此迁移时不能引用任何吞吐结论，只能按机制判断：并发上升时显存先于算力成为瓶颈，调度器必须在准入阶段就按 KV 预算做拒绝或降级，而不是等到显存溢出再补救。</p>\n<p>代价判断：流式输出把延迟指标从“端到端完成时间”拆成“首块延迟 + 块间间隔”，SLO 口径随之改变；若沿用原方案的端到端口径做容量规划，会系统性高估可承载并发。这是迁移中最容易犯的口径错误。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-55\">五十五 · 规模上限：三个硬约束而非一个</h3>\n<p>本方案的规模上限不由单一维度决定，而是三条约束同时收紧。其一是注意力显存随帧数与 token 数线性增长，序列越长，单请求驻留的激活与 KV 越大；其二是分块重叠的拼接开销随块数增长，块越多，中间缓冲与拼接算力越多；其三是 VAE 解码的带宽压力随输出分辨率与时长增长。三者中任一先触顶，整体规模就到头。材料未给出具体帧数、token 规模与硬件档位数字，因此不能给出“支持多长视频”的定量结论，只能给出判断顺序：先测解码带宽是否先饱和，再测注意力显存，最后看拼接开销——因为解码是端到端延迟的固定组成，而拼接开销可以通过减少块数换取显存。</p>\n<p>迁移到别的模型时，这个顺序会变：若目标模型 KV 增长是常数，注意力显存不再是上限，规模瓶颈直接落到解码带宽与拼接开销上。工程判断是：规模上限要按目标模型重新测，不能把本方案的瓶颈顺序当作通用结论。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-56\">五十六 · 哪里不适用：三条明确的否定判断</h3>\n<p>第一，目标模型若没有时间维度的注意力交互（逐帧独立生成再拼接），分块与重叠的一致性机制失去意义，本方案的核心收益消失，只剩精度与显存管理的通用部分可复用。第二，若目标领域对数值稳定性要求极高而材料未给出精度切换阈值，NVFP4/FP8 的低精度路径不能默认开启，必须先做解码质量的机制性走查，否则失败模式会从显存溢出变成质量不可接受。第三，若部署侧硬件档位与并行拓扑未定（材料明确未给出 B200/B300/GB200 NVL72 的具体配置数字），本方案里依赖并行切分的吞吐假设无法落地，此时只能按单卡显存预算做保守容量规划。</p>\n<p>这三条否定的共同点是：它们都不是“调参能解决”的问题，而是计算图结构、数值稳定性、硬件拓扑层面的不匹配。迁移的正确做法是先判定这三条是否成立，成立则本方案只保留精度与显存管理的骨架，分块、重叠、批量调度的具体策略全部重写；不成立才谈移植细节。</p>\n\n<h3 id=\"paper-video-diffusion-models-2022-sec-57\">五十七 · 迁移边界：什么能搬、什么必须重算、什么根本不该搬</h3>\n<p>这套推理方案的可迁移部分其实只有骨架：时空注意力作为计算主干、VAE 解码作为像素还原出口、分块与重叠作为长序列切分手段、批量与流式输出作为调度外壳。骨架之所以能搬，是因为它对应的是显存与带宽这两个物理约束，而不是某个模型的私有结构。但骨架搬过去之后，每一段连接都要按目标模型重算代价。以 <span class=\"formula\">$$\\mathrm{Mem}\\propto N_{\\mathrm{frame}}\\cdot N_{\\mathrm{token}}\\cdot d$$</span> 为例，帧数与 token 数的乘积决定了注意力的显存下限，迁移到图像扩散时帧数退化为 1，分块与重叠整套机制直接失效，重叠拼接的额外计算归零，但 VAE 解码的带宽压力反而因为单帧高分辨率而集中到一次解码调用上；迁移到音频或时序信号扩散时，token 维度换成时间步，时空注意力的二维结构塌缩为一维，重叠策略仍可用但拼接一致性判据要换成相位或能量连续性。判断标准很硬：只要目标负载的序列长度不再由“帧×空间 token”决定，分块与重叠的参数就必须重新推导，不能沿用。</p>\n<p>失效条件集中在三处。第一，KV cache 与并发的耦合在流式输出下最脆弱：并发上升时 KV cache 与显存占用同步上升，调度器若按固定批大小排队，长视频请求会把短请求挤出显存窗口，形成队头阻塞；此时正确做法是把分块粒度作为调度单位而不是把整段视频作为单位，代价是块间重叠被重复计算，吞吐按重叠比例线性折损。第二，NVFP4/FP8 的精度切换不是无损开关：精度选择同时影响解码质量与显存占用，VAE 解码器对低位宽的敏感度高于注意力算子，因为像素还原是逐元素重建，量化误差不会被 softmax 归一化吸收；把注意力降到 NVFP4 而解码保留 FP8 是常见折中，代价是两套权重常驻显存，显存收益被部分抵消。第三，失败模式里显存溢出与带宽瓶颈的监控阈值材料未给出，工程上只能以“单块解码峰值显存 + 重叠区副本”作为硬上限来设水位线，超过即触发分块回退，而不是等 OOM 后重试。</p>\n<p>规模上限不在算力，在拼接开销与调度粒度的乘积。设分块数为 <span class=\"formula\">$$N_{\\mathrm{chunk}}$$</span>、重叠比例为 <span class=\"formula\">$$r$$</span>，则有效计算量为 <span class=\"formula\">$$(1+r)\\cdot N_{\\mathrm{chunk}}$$</span> 倍的单块计算，重叠区既要算又要存，显存峰值约按 <span class=\"formula\">$$(1+r)$$</span> 放大。当 <span class=\"formula\">$$r$$</span> 增大以换取块间一致性时，吞吐下降与显存上升同时发生，这就是长视频的实际上限：不是不能更长，而是每延长一段，重叠副本与 KV cache 共同挤压并发窗口。迁到 B200/B300/GB200 NVL72 这类档位时，材料未给出具体配置数字，只能定性判断——带宽更宽会推迟瓶颈出现的位置，但不会消除重叠开销，因为重叠是算法层代价而非访存层代价。真正不该搬的是“以整段视频为调度单位”的假设：任何目标领域只要请求时长分布长尾明显，就必须改成块级调度，否则流式输出的首块延迟会被整段排队吞掉。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>可直接复用</th><th>必须重算</th><th>主要代价</th></tr></thead><tbody><tr><td>图像扩散</td><td>VAE 解码、精度管理</td><td>分块与重叠失效、注意力降为一维</td><td>解码带宽集中、显存峰值单点</td></tr><tr><td>长视频扩展</td><td>块级调度、KV cache 策略</td><td>重叠比例与拼接判据</td><td>重叠副本放大显存、吞吐按 (1+r) 折损</td></tr><tr><td>时序/音频扩散</td><td>流式输出外壳</td><td>注意力结构、一致性判据</td><td>拼接开销转为连续性校验</td></tr></tbody></table>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 121\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Video Diffusion Models</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"65.5\" x2=\"271.0\" y2=\"65.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 61.0 L 270.0 70.0 L 278.0 65.5 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"65.5\" x2=\"515.0\" y2=\"65.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 61.0 L 514.0 70.0 L 522.0 65.5 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"111.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2022 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Video Diffusion Models 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称与规模</td></tr><tr><td>基线</td><td>材料未给出具体基线模型与对比方法</td></tr><tr><td>主要结果</td><td>材料未给出可核验的吞吐、延迟与显存数字；仅能确认推理链路包含时空注意力、V…</td></tr><tr><td>消融</td><td>材料未给出消融实验设置与数字；仅能从机制层面指出精度模式、分块大小与重叠长…</td></tr><tr><td>局限</td><td>材料未给出失败模式与监控指标的具体阈值；可归纳的局限包括长视频分块与重叠带…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-video-diffusion-models-2022 · 共 9 个片段</p>\n";break;}}})();
